from __future__ import annotations

DEFAULTS: dict = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}

_FIELD_VALIDATORS: list[tuple[str, callable]] = [
    ("port", lambda v: type(v) is int and 1 <= v <= 65535),
    ("host", lambda v: isinstance(v, str) and len(v) > 0),
    ("workers", lambda v: type(v) is int and v >= 1),
    ("debug", lambda v: type(v) is bool),
]


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    config = dict(DEFAULTS)

    for key, validator in _FIELD_VALIDATORS:
        if key in raw:
            value = raw[key]
            if not validator(value):
                return dict(DEFAULTS)
            config[key] = value

    return config

