from collections import defaultdict

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if "width" not in grid or "height" not in grid or "cell_size" not in grid:
        return {"ok": False, "error": "bad grid"}
    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or width < 1 or width > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    if not isinstance(height, int) or height < 1 or height > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    if not isinstance(cell_size, int) or cell_size < 1:
        return {"ok": False, "error": "bad cell size"}
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = defaultdict(int)
    counts = defaultdict(int)
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if "x" not in obs or not isinstance(obs["x"], int):
            return {"ok": False, "error": "bad observation"}
        if "y" not in obs or not isinstance(obs["y"], int):
            return {"ok": False, "error": "bad observation"}
        if "value" not in obs or not isinstance(obs["value"], int):
            return {"ok": False, "error": "bad observation"}
        if "quality" not in obs or not isinstance(obs["quality"], int):
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < 0 or obs["quality"] > 100:
            return {"ok": False, "error": "bad observation"}

        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        x = obs["x"]
        if x < 0:
            dropped = dropped + 1
            continue
        col = x // cell_size
        if col >= width:
            if x - width * cell_size < tolerance:
                col = width - 1
            else:
                dropped = dropped + 1
                continue

        y = obs["y"]
        if y < 0:
            dropped = dropped + 1
            continue
        row = y // cell_size
        if row >= height:
            if y - height * cell_size < tolerance:
                row = height - 1
            else:
                dropped = dropped + 1
                continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    rows = []
    for row in range(height):
        cells = [
            sums[(row, col)] // counts[(row, col)] if (row, col) in counts
            else fill_value
            for col in range(width)
        ]
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return ";".join([
        f"cells={total_cells}",
        f"filled={filled}",
        f"dropped={dropped}",
        f"rejected={rejected}",
        f"saturated={saturated}",
        f"coverage={coverage}",
    ])

from __future__ import annotations

from typing import Any

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

_REQUIRED_GRID_FIELDS = {"width", "height", "cell_size"}
_REQUIRED_OBS_FIELDS = {"x", "y", "value", "quality"}


def _check_has_fields(data: dict, fields: set, error_msg: str) -> dict | None:
    if not fields.issubset(data):
        return {"ok": False, "error": error_msg}
    return None


def _check_int_range(value: int, minimum: int, maximum: int, name: str) -> dict | None:
    if not isinstance(value, int) or not (minimum <= value <= maximum):
        return {"ok": False, "error": f"bad {name}"}
    return None


def _validate_grid(raw: dict) -> dict | None:
    if not isinstance(raw["grid"], dict):
        return {"ok": False, "error": "bad grid"}
    grid = raw["grid"]
    err = _check_has_fields(grid, _REQUIRED_GRID_FIELDS, "bad grid")
    if err:
        return err
    for field, minimum, maximum, name in [
        ("width", 1, MAX_DIM, "width"),
        ("height", 1, MAX_DIM, "height"),
    ]:
        err = _check_int_range(grid[field], minimum, maximum, name)
        if err:
            return err
    err = _check_int_range(grid["cell_size"], 1, MAX_DIM, "cell_size")
    if err:
        return err
    return None


def _validate_raw(raw: dict) -> dict | None:
    err = _check_has_fields(raw, {"grid", "observations", "fill_value"}, "missing field")
    if err:
        return err
    err = _validate_grid(raw)
    if err:
        return err
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    if not isinstance(raw["observations"], list):
        return {"ok": False, "error": "bad observations"}
    return None


def _validate_observation(obs: dict) -> dict | None:
    if not isinstance(obs, dict):
        return {"ok": False, "error": "bad observation"}
    err = _check_has_fields(obs, _REQUIRED_OBS_FIELDS, "bad observation")
    if err:
        return err
    for field in ("x", "y", "value", "quality"):
        if not isinstance(obs[field], int):
            return {"ok": False, "error": "bad observation"}
    if not (0 <= obs["quality"] <= 100):
        return {"ok": False, "error": "bad observation"}
    return None


def _try_wrap_index(
    value: int, dimension: int, cell_size: int, tolerance: int,
) -> int | None:
    if value < 0:
        return None
    idx = value // cell_size
    if idx < dimension:
        return idx
    if value - dimension * cell_size < tolerance:
        return dimension - 1
    return None


def _wrap_coords(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int,
) -> tuple[int, int] | None:
    col = _try_wrap_index(obs["x"], width, cell_size, tolerance)
    if col is None:
        return None
    row = _try_wrap_index(obs["y"], height, cell_size, tolerance)
    if row is None:
        return None
    return (row, col)


def _classify_observation(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int,
) -> dict:
    action: str
    key: tuple[int, int] | None = None
    if obs["quality"] < MIN_QUALITY:
        action = "rejected"
    else:
        coord = _wrap_coords(obs, width, height, cell_size, tolerance)
        if coord is None:
            action = "dropped"
        else:
            key = coord
            action = "add"
    return {"action": action, "key": key, "quality": obs["quality"]}


def _build_grid(
    observations: list[dict],
    width: int,
    height: int,
    cell_size: int,
    fill_value: int,
) -> dict[str, Any]:
    sums: dict[tuple[int, int], int] = {}
    counts: dict[tuple[int, int], int] = {}
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        error = _validate_observation(obs)
        if error is not None:
            return error
        result = _classify_observation(obs, width, height, cell_size, tolerance)
        action = result["action"]
        if action == "rejected":
            rejected += 1
        elif action == "dropped":
            dropped += 1
        else:
            key = result["key"]
            quality = result["quality"]
            if counts.get(key, 0) >= SATURATION_LIMIT:
                saturated += 1
            else:
                sums[key] = sums.get(key, 0) + obs["value"]
                counts[key] = counts.get(key, 0) + 1
                if quality < GOOD_QUALITY:
                    degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(
        width * height, len(counts), dropped, rejected, saturated, coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def accumulate_grid(raw: object) -> dict[str, Any]:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}

    error = _validate_raw(raw)
    if error is not None:
        return error

    grid = raw["grid"]
    width: int = grid["width"]
    height: int = grid["height"]
    cell_size: int = grid["cell_size"]
    fill_value: int = raw["fill_value"]
    observations: list[dict] = raw["observations"]

    return _build_grid(observations, width, height, cell_size, fill_value)


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums.get((row, col), 0) // counts.get((row, col), 1) if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    return [
        [
            "empty" if (row, col) not in counts
            else "degraded" if (row, col) in degraded
            else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return f"cells={total_cells};filled={filled};dropped={dropped};rejected={rejected};saturated={saturated};coverage={coverage}"

