    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if not _is_non_bool_int(obs.get("x")):
            return {"ok": False, "error": "bad observation"}
        if not _is_non_bool_int(obs.get("y")):
            return {"ok": False, "error": "bad observation"}
        if not _is_non_bool_int(obs.get("value")):
            return {"ok": False, "error": "bad observation"}
        if not _is_non_bool_int(obs.get("quality")):
            return {"ok": False, "error": "bad observation"}
        quality = obs["quality"]
        if quality < 0 or quality > 100:
            return {"ok": False, "error": "bad observation"}

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        x = obs["x"]
        if x < 0:
            dropped += 1
            continue
        col, offset = divmod(x, cell_size)
        if col >= width:
            if col == width and offset < tolerance:
                col = width - 1
            else:
                dropped += 1
                continue

        y = obs["y"]
        if y < 0:
            dropped += 1
            continue
        row, offset = divmod(y, cell_size)
        if row >= height:
            if row == height and offset < tolerance:
                row = height - 1
            else:
                dropped += 1
                continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if quality < GOOD_QUALITY:
            degraded.add(key)

    cells = _averaged_rows(sums, counts, width, height, raw["fill_value"])
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value
         for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(counts: dict, degraded: set, width: int, height: int) -> list:
    return [
        ["empty" if (row, col) not in counts
         else "degraded" if (row, col) in degraded
         else "good"
         for col in range(width)]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
