        if _try_map_position(obs, width, height, cell_size, tolerance, counts) is None:
            continue

        key = (obs["y"] // cell_size, obs["x"] // cell_size)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] += 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    return sums, counts, degraded, dropped, rejected, saturated


def _try_map_position(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int, counts: dict
) -> tuple[int, int] | None:
    x, y = obs["x"], obs["y"]
    if x < 0 or y < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return None
    key = (row, col)
    if counts.get(key, 0) >= SATURATION_LIMIT:
        return None
    return key


