from __future__ import annotations

from collections import defaultdict


MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5


def accumulate_grid(raw: object) -> dict:
    validation = _validate_raw(raw)
    if isinstance(validation, dict) and "error" in validation:
        return validation
    grid, fill_value, observations = validation
    grid_check = _validate_grid(grid)
    if isinstance(grid_check, dict) and "error" in grid_check:
        return grid_check
    width, height, cell_size = grid_check
    obs_check = _validate_observations(observations)
    if isinstance(obs_check, dict) and "error" in obs_check:
        return obs_check
    tolerance = cell_size // 2
    return _build_result(_accumulate(observations, width, height, cell_size, fill_value, tolerance))


def _validate_raw(raw: object) -> dict | tuple[dict, int, list]:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if "grid" not in raw or "observations" not in raw or "fill_value" not in raw:
        return {"ok": False, "error": "missing field"}
    return raw["grid"], raw["fill_value"], raw["observations"]


def _validate_grid(grid: object) -> dict | tuple[int, int, int]:
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    grid_keys = ("width", "height", "cell_size")
    if not all(k in grid for k in grid_keys):
        return {"ok": False, "error": "bad grid"}
    width_err = _validate_width(grid["width"])
    if width_err:
        return width_err
    height_err = _validate_height(grid["height"])
    if height_err:
        return height_err
    cell_err = _validate_cell_size(grid["cell_size"])
    if cell_err:
        return cell_err
    return grid["width"], grid["height"], grid["cell_size"]


def _validate_width(value: object) -> dict | None:
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return {"ok": False, "error": "bad width"}
    return None


def _validate_height(value: object) -> dict | None:
    if not isinstance(value, int) or value < 1 or value > MAX_DIM:
        return {"ok": False, "error": "bad height"}
    return None


def _validate_cell_size(value: object) -> dict | None:
    if not isinstance(value, int) or value < 1:
        return {"ok": False, "error": "bad cell size"}
    return None


def _validate_observations(observations: object) -> dict | None:
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    return None


def _build_result(acc: dict) -> dict:
    sums, counts, degraded, dropped, rejected, saturated, width, height, fill_value = acc
    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _compute_coverage(counts, width, height)
    line = _summary_line(
        total_cells=width * height,
        filled=len(counts),
        dropped=dropped,
        rejected=rejected,
        saturated=saturated,
        coverage=coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _accumulate(
    observations: list,
    width: int,
    height: int,
    cell_size: int,
    fill_value: int,
    tolerance: int,
) -> tuple[dict, dict, dict, int, int, int, int, int, int]:
    sums: dict[tuple[int, int], int] = defaultdict(int)
    counts: dict[tuple[int, int], int] = defaultdict(int)
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        valid = _validate_obs(obs)
        if valid is not None:
            return sums, counts, degraded, 0, 0, 0, 0, 0, 0
        mapped = _map_obs(obs, width, height, cell_size, tolerance)
        if mapped.get("rejected"):
            rejected += 1
            continue
        if mapped.get("dropped"):
            dropped += 1
            continue
        key, value = mapped["key"], mapped["value"]
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += value
        counts[key] += 1
        if mapped["degraded"]:
            degraded[key] = True
    return sums, counts, degraded, dropped, rejected, saturated, width, height, fill_value


def _validate_obs(obs: object) -> dict | None:
    if not isinstance(obs, dict):
        return {"error": "bad observation"}
    required_keys = ("x", "y", "value", "quality")
    if not all(k in obs for k in required_keys):
        return {"error": "bad observation"}
    if not all(isinstance(obs[k], int) for k in required_keys):
        return {"error": "bad observation"}
    if obs["quality"] < 0 or obs["quality"] > 100:
        return {"error": "bad observation"}
    return None


def _map_obs(
    obs: dict, width: int, height: int, cell_size: int, tolerance: int,
) -> dict:
    if obs["quality"] < MIN_QUALITY:
        return {"rejected": True}
    x, y = obs["x"], obs["y"]
    if x < 0 or y < 0:
        return {"dropped": True}
    col = _clamp_col(x, cell_size, width, tolerance)
    row = _clamp_row(y, cell_size, height, tolerance)
    if col is None or row is None:
        return {"dropped": True}
    return {
        "key": (row, col),
        "value": obs["value"],
        "degraded": obs["quality"] < GOOD_QUALITY,
    }


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            cells.append(sums[key] // counts[key] if key in counts else fill_value)
        rows.append(cells)
    return rows


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif degraded.get(key):
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _compute_coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    total = width * height
    return len(counts) * 100 // total if total else 0


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (
        f"cells={total_cells}"
        f";filled={filled}"
        f";dropped={dropped}"
        f";rejected={rejected}"
        f";saturated={saturated}"
        f";coverage={coverage}"
    )


def _clamp_col(
    x: int, cell_size: int, width: int, tolerance: int
) -> int | None:
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            return width - 1
        return None
    return col


def _clamp_row(
    y: int, cell_size: int, height: int, tolerance: int
) -> int | None:
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            return height - 1
        return None
    return row

