def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}

    grid = raw.get("grid")
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}

    grid_data = _validate_grid(grid)
    if grid_data is None:
        return {"ok": False, "error": "bad grid"}

    err = _validate_top_level(raw, grid_data)
    if err:
        return err

    width = grid_data["width"]
    height = grid_data["height"]
    cell_size = grid_data["cell_size"]
    fill_value = raw["fill_value"]
    observations = raw["observations"]

    result = _process_observations(observations, width, height, cell_size)
    if isinstance(result, dict):
        return result

    sums, counts, degraded, dropped, rejected, saturated = result

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, width, height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _validate_grid(grid: dict) -> dict | None:
    if not _grid_has_required_keys(grid):
        return None
    if not _grid_values_are_ints(grid):
        return None
    if not _grid_values_in_range(grid):
        return None
    return {"width": grid["width"], "height": grid["height"], "cell_size": grid["cell_size"]}


def _grid_has_required_keys(grid: dict) -> bool:
    return all(k in grid for k in ("width", "height", "cell_size"))


def _grid_values_are_ints(grid: dict) -> bool:
    return all(isinstance(grid[k], int) for k in ("width", "height", "cell_size"))


def _grid_values_in_range(grid: dict) -> bool:
    return (
        1 <= grid["width"] <= MAX_DIM
        and 1 <= grid["height"] <= MAX_DIM
        and grid["cell_size"] >= 1
    )


def _validate_top_level(raw: dict, grid_data: dict) -> dict | None:
    fill_value = raw.get("fill_value")
    observations = raw.get("observations")
    if fill_value is None or observations is None:
        return {"ok": False, "error": "missing field"}
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}
    return None


def _process_observations(
    observations: list, width: int, height: int, cell_size: int
) -> tuple[dict, dict, dict, int, int, int] | dict:
    sums: dict[tuple[int, int], int] = defaultdict(int)
    counts: dict[tuple[int, int], int] = defaultdict(int)
    degraded: dict[tuple[int, int], bool] = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _validate_observation(obs):
            return {"ok": False, "error": "bad observation"}

        quality = obs["quality"]
        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col, row = _map_coords(obs["x"], obs["y"], cell_size, width, height, tolerance)
        if row is None or col is None:
            dropped += 1
            continue

        key = (row, col)
        if counts[key] >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] += obs["value"]
        counts[key] += 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    return sums, counts, degraded, dropped, rejected, saturated


def _validate_observation(obs: object) -> bool:
    if not isinstance(obs, dict):
        return False
    if not _obs_has_required_fields(obs):
        return False
    if not _obs_fields_are_ints(obs):
        return False
    if not _obs_quality_in_range(obs):
        return False
    return True


def _obs_has_required_fields(obs: dict) -> bool:
    return all(k in obs for k in ("x", "y", "value", "quality"))


def _obs_fields_are_ints(obs: dict) -> bool:
    return all(isinstance(obs[k], int) for k in ("x", "y", "value", "quality"))


def _obs_quality_in_range(obs: dict) -> bool:
    return 0 <= obs["quality"] <= 100


def _map_coords(
    x: int, y: int, cell_size: int, width: int, height: int, tolerance: int
) -> tuple[int | None, int | None]:
    if x < 0 or y < 0:
        return (None, None)
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            col = width - 1
        else:
            return (None, None)
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            row = height - 1
        else:
            return (None, None)
    return (col, row)


def _averaged_rows(
    sums: dict[tuple[int, int], int],
    counts: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    return [
        [sums[(row, col)] // counts[(row, col)] if (row, col) in counts else fill_value for col in range(width)]
        for row in range(height)
    ]


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: dict[tuple[int, int], bool],
    width: int,
    height: int,
) -> list[list[str]]:
    return [
        [
            "empty" if (row, col) not in counts
            else "degraded" if (row, col) in degraded
            else "good"
            for col in range(width)
        ]
        for row in range(height)
    ]


def _coverage(counts: dict, width: int, height: int) -> int:
    return len(counts) * 100 // (width * height)


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return f"cells={total_cells};filled={filled};dropped={dropped};rejected={rejected};saturated={saturated};coverage={coverage}"

