    if not isinstance(observations, list):
        return None
    return grid, observations, raw["fill_value"]


def accumulate_grid(raw: object) -> dict:
    validated = _validate_raw(raw)
    if validated is None:
        return {"ok": False, "error": "bad input"}
    grid, observations, fill_value = validated

    result = _process_observations(observations, grid["width"], grid["height"], grid["cell_size"])
    if result.get("ok") is False:
        return result

    cells = _averaged_rows(result["counts"], result["sums"], width, height, raw["fill_value"])
    flags = _flag_rows(result["counts"], result["degraded"], width, height)
    coverage = _coverage(result["counts"], width, height)
    line = _summary_line(
        width * height, len(result["counts"]), result["dropped"],
        result["rejected"], result["saturated"], coverage,
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": result["dropped"],
        "rejected": result["rejected"],
        "saturated": result["saturated"],
        "coverage": coverage,
        "line": line,
    }


def _process_observations(
    observations: list,
    width: int,
    height: int,
    cell_size: int,
) -> dict:
    counts: dict[tuple[int, int], int] = {}
    sums: dict[tuple[int, int], int] = {}
    degraded: set[tuple[int, int]] = set()
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        err = _validate_observation(obs)
        if err is not None:
            return {"ok": False, "error": err}

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        col = _try_col(obs["x"], width, cell_size, tolerance)
        if col is None:
            dropped += 1
            continue

        row = _try_row(obs["y"], height, cell_size, tolerance)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded.add(key)

    return {
        "counts": counts,
        "sums": sums,
        "degraded": degraded,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
    }


def _validate_observation(obs: object) -> str | None:
    if not isinstance(obs, dict):
        return "bad observation"
    if not all(isinstance(obs.get(k), int) for k in _REQUIRED_OBS_KEYS):
        return "bad observation"
    if obs["quality"] < 0 or obs["quality"] > 100:
        return "bad observation"
    return None


def _try_col(x: int, width: int, cell_size: int, tolerance: int) -> int | None:
    if x < 0:
        return None
    col = x // cell_size
    if col >= width:
        if x - width * cell_size < tolerance:
            return width - 1
        return None
    return col


def _try_row(y: int, height: int, cell_size: int, tolerance: int) -> int | None:
    if y < 0:
        return None
    row = y // cell_size
    if row >= height:
        if y - height * cell_size < tolerance:
            return height - 1
        return None
    return row


def _averaged_rows(
    counts: dict[tuple[int, int], int],
    sums: dict[tuple[int, int], int],
    width: int,
    height: int,
    fill_value: int,
) -> list[list[int]]:
    return [
        [sums[(r, c)] // counts[(r, c)] if (r, c) in counts else fill_value
         for c in range(width)]
        for r in range(height)
    ]


def _flag_rows(
    counts: dict[tuple[int, int], int],
    degraded: set[tuple[int, int]],
    width: int,
    height: int,
) -> list[list[str]]:
    return [
        [
            "empty" if (r, c) not in counts
            else "degraded" if (r, c) in degraded
            else "good"
            for c in range(width)
        ]
        for r in range(height)
    ]


def _coverage(counts: dict[tuple[int, int], int], width: int, height: int) -> int:
    if width * height == 0:
        return 0
    return len(counts) * 100 // (width * height)


def _summary_line(
    total_cells: int,
    filled: int,
    dropped: int,
    rejected: int,
    saturated: int,
    coverage: int,
) -> str:
    return (f"cells={total_cells}"
            f";filled={filled}"
            f";dropped={dropped}"
            f";rejected={rejected}"
            f";saturated={saturated}"
            f";coverage={coverage}")

