from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    member = raw_member
    payment = raw_payment
    if "id" not in member or "status" not in member or "tier" not in member:
        return {"ok": False, "error": "missing member field"}
    if "amount" not in payment or "method" not in payment:
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(member["id"], str) or len(member["id"]) == 0:
        return {"ok": False, "error": "bad member id"}

    status = member["status"]
    if status == "banned":
        return {"ok": False, "error": "member banned"}

    if status == "active":
        if member["tier"] != "basic" and member["tier"] != "gold":
            return {"ok": False, "error": "unknown tier"}
        if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
            return {"ok": False, "error": "bad amount"}
        if payment["method"] != "card" and payment["method"] != "transfer":
            return {"ok": False, "error": "unsupported method"}
        fee = TIER_FEES[member["tier"]]
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        if payment["method"] == "card":
            receipt = "card:" + member["id"] + ":renewed:" + str(fee)
        else:
            receipt = "transfer:" + member["id"] + ":renewed:" + str(fee)
        return {"ok": True, "status": "renewed", "fee": fee, "receipt": receipt}

    if status == "lapsed":
        if member["tier"] != "basic" and member["tier"] != "gold":
            return {"ok": False, "error": "unknown tier"}
        if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
            return {"ok": False, "error": "bad expiry"}
        if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
            return {"ok": False, "error": "bad amount"}
        if payment["method"] != "card" and payment["method"] != "transfer":
            return {"ok": False, "error": "unsupported method"}
        if member["expired_days"] <= GRACE_DAYS:
            fee = TIER_FEES[member["tier"]] + LATE_FEE
            new_status = "renewed"
        else:
            fee = TIER_FEES[member["tier"]] + REINSTATE_SURCHARGE
            new_status = "reinstated"
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        if payment["method"] == "card":
            receipt = "card:" + member["id"] + ":" + new_status + ":" + str(fee)
        else:
            receipt = "transfer:" + member["id"] + ":" + new_status + ":" + str(fee)
        return {"ok": True, "status": new_status, "fee": fee, "receipt": receipt}

    if status == "suspended":
        if member["tier"] != "basic" and member["tier"] != "gold":
            return {"ok": False, "error": "unknown tier"}
        if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
            return {"ok": False, "error": "bad strikes"}
        if member["strikes"] >= MAX_STRIKES:
            return {"ok": False, "error": "too many strikes"}
        if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
            return {"ok": False, "error": "bad amount"}
        if payment["method"] != "card" and payment["method"] != "transfer":
            return {"ok": False, "error": "unsupported method"}
        fee = TIER_FEES[member["tier"]] + TIER_FEES[member["tier"]] // 2
        if payment["amount"] < fee:
            return {"ok": False, "error": "insufficient payment"}
        if payment["method"] == "card":
            receipt = "card:" + member["id"] + ":reactivated:" + str(fee)
        else:
            receipt = "transfer:" + member["id"] + ":reactivated:" + str(fee)
        return {"ok": True, "status": "reactivated", "fee": fee, "receipt": receipt}

    return {"ok": False, "error": "unknown status"}

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
VALID_METHODS = {"card", "transfer"}


def _guard_inputs(raw_member: dict, raw_payment: dict) -> dict | None:
    if not isinstance(raw_member, dict) or not isinstance(raw_payment, dict):
        return {"ok": False, "error": "malformed input"}
    if not {"id", "status", "tier"}.issubset(raw_member):
        return {"ok": False, "error": "missing member field"}
    if not {"amount", "method"}.issubset(raw_payment):
        return {"ok": False, "error": "missing payment field"}
    if not isinstance(raw_member["id"], str) or not raw_member["id"]:
        return {"ok": False, "error": "bad member id"}
    return None


def _validate_payment_fields(member: dict, payment: dict) -> dict | None:
    if member["tier"] not in TIER_FEES:
        return {"ok": False, "error": "unknown tier"}
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in VALID_METHODS:
        return {"ok": False, "error": "unsupported method"}
    return None


def _calc_fee(tier: str, grace: bool = False, surcharge: bool = False, penalty: bool = False) -> int:
    fee = TIER_FEES[tier]
    if grace:
        fee += LATE_FEE
    if surcharge:
        fee += REINSTATE_SURCHARGE
    if penalty:
        fee += fee // 2
    return fee


def _success(status: str, fee: int, member_id: str, method: str) -> dict:
    return {
        "ok": True,
        "status": status,
        "fee": fee,
        "receipt": f"{method}:{member_id}:{status}:{fee}",
    }


def _handle_active(member: dict, payment: dict) -> dict:
    if err := _validate_payment_fields(member, payment):
        return err
    fee = _calc_fee(member["tier"])
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return _success("renewed", fee, member["id"], payment["method"])


def _handle_lapsed(member: dict, payment: dict) -> dict:
    if "expired_days" not in member or not isinstance(member["expired_days"], int) or member["expired_days"] < 0:
        return {"ok": False, "error": "bad expiry"}
    if err := _validate_payment_fields(member, payment):
        return err
    grace = member["expired_days"] <= GRACE_DAYS
    fee = _calc_fee(member["tier"], grace=grace, surcharge=not grace)
    status = "renewed" if grace else "reinstated"
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return _success(status, fee, member["id"], payment["method"])


def _handle_suspended(member: dict, payment: dict) -> dict:
    if "strikes" not in member or not isinstance(member["strikes"], int) or member["strikes"] < 0:
        return {"ok": False, "error": "bad strikes"}
    if member["strikes"] >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    if err := _validate_payment_fields(member, payment):
        return err
    fee = _calc_fee(member["tier"], penalty=True)
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return _success("reactivated", fee, member["id"], payment["method"])


_STATUS_HANDLERS = {
    "active": _handle_active,
    "lapsed": _handle_lapsed,
    "suspended": _handle_suspended,
}


def process_renewal(raw_member: object, raw_payment: object) -> dict:
    if err := _guard_inputs(raw_member, raw_payment):
        return err

    status = raw_member["status"]

    if status == "banned":
        return {"ok": False, "error": "member banned"}

    handler = _STATUS_HANDLERS.get(status)
    if handler is None:
        return {"ok": False, "error": "unknown status"}

    return handler(raw_member, raw_payment)

from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}

VALID_TIERS = {"basic", "gold"}


def _validate_payment(payment: dict) -> dict | None:
    if not isinstance(payment["amount"], int) or payment["amount"] <= 0:
        return {"ok": False, "error": "bad amount"}
    if payment["method"] not in ("card", "transfer"):
        return {"ok": False, "error": "unsupported method"}
    return None


def _validate_tier(tier: str) -> dict | None:
    if tier not in VALID_TIERS:
        return {"ok": False, "error": "unknown tier"}
    return None


def _check_sufficient(payment: dict, fee: int) -> dict | None:
    if payment["amount"] < fee:
        return {"ok": False, "error": "insufficient payment"}
    return None


def _build_receipt(method: str, member_id: str, status: str, fee: int) -> str:
    return f"{method}:{member_id}:{status}:{fee}"


def _handle_active(member: dict, payment: dict) -> dict:
    err = _validate_tier(member["tier"])
    if err:
        return err
    err = _validate_payment(payment)
    if err:
        return err
    fee = TIER_FEES[member["tier"]]
    err = _check_sufficient(payment, fee)
    if err:
        return err
    return {
        "ok": True,
        "status": "renewed",
        "fee": fee,
        "receipt": _build_receipt(payment["method"], member["id"], "renewed", fee),
    }


def _compute_lapsed_fee(tier: str, expired_days: int) -> tuple[int, str]:
    if expired_days <= GRACE_DAYS:
        return TIER_FEES[tier] + LATE_FEE, "renewed"
    return TIER_FEES[tier] + REINSTATE_SURCHARGE, "reinstated"


def _handle_lapsed(member: dict, payment: dict) -> dict:
    err = _validate_tier(member["tier"])
    if err:
        return err
    expired_days = member.get("expired_days")
    if not isinstance(expired_days, int) or expired_days < 0:
        return {"ok": False, "error": "bad expiry"}
    err = _validate_payment(payment)
    if err:
        return err
    fee, new_status = _compute_lapsed_fee(member["tier"], expired_days)
    err = _check_sufficient(payment, fee)
    if err:
        return err
    return {
        "ok": True,
        "status": new_status,
        "fee": fee,
        "receipt": _build_receipt(payment["method"], member["id"], new_status, fee),
    }


def _handle_suspended(member: dict, payment: dict) -> dict:
    err = _validate_tier(member["tier"])
    if err:
        return err
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return {"ok": False, "error": "bad strikes"}
    if strikes >= MAX_STRIKES:
        return {"ok": False, "error": "too many strikes"}
    err = _validate_payment(payment)
    if err:
        return err
    base = TIER_FEES[member["tier"]]
    fee = base + base // 2
    err = _check_sufficient(payment, fee)
    if err:
        return err
    return {
        "ok": True,
        "status": "reactivated",
        "fee": fee,
        "receipt": _build_receipt(payment["method"], member["id"], "reactivated", fee),
    }


HANDLERS: dict[str, callable] = {
    "active": _handle_active,
    "lapsed": _handle_lapsed,
