from __future__ import annotations

from itertools import groupby


def password_strength(pw: str) -> int:
    score = 0
    pw_len = len(pw)

    if pw_len >= 8:
        score += 1
    elif pw_len < 4:
        score -= 1

    has_lower = has_upper = has_digit = has_symbol = False

    for ch in pw:
        if ch.islower():
            has_lower = True
        elif ch.isupper():
            has_upper = True
        elif ch.isdigit():
            has_digit = True
        else:
            has_symbol = True

    if has_lower:
        score += 1
    if has_upper:
        score += 1
    if has_digit:
        score += 1
    if has_symbol:
        score += 1

    max_run = max((sum(1 for _ in g) for _, g in groupby(pw)), default=0)
    if max_run >= 3:
        score -= 2
    elif max_run >= 2:
        score -= 1

    if pw_len >= 12 and has_symbol:
        score += 1

    return max(score, 0)

