def _length_score(length: int) -> int:
    if length >= 8:
        return 1
    if length < 4:
        return -1
    return 0


def _char_class_count(pw: str) -> int:
    count = 0
    has_lower = False
    has_upper = False
    has_digit = False
    has_symbol = False
    for ch in pw:
        if ch.islower():
            has_lower = True
        elif ch.isupper():
            has_upper = True
        elif ch.isdigit():
            has_digit = True
        elif not ch.isalnum():
            has_symbol = True
    return int(has_lower) + int(has_upper) + int(has_digit) + int(has_symbol)


def _has_symbol(pw: str) -> bool:
    return any(not ch.isalnum() for ch in pw)


_REPEAT_PENALTY = {
    0: 0,
    1: -1,
    2: -1,
    3: -2,
    4: -2,
}


def _repeat_penalty(count: int) -> int:
    return _REPEAT_PENALTY.get(count, -2)


def _symbol_bonus(length: int, has_symbol: bool) -> int:
    if length >= 12 and has_symbol:
        return 1
    return 0


def _count_consecutive_repeats(pw: str) -> int:
    return sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])


def password_strength(pw: str) -> int:
    length = len(pw)
    has_symbol = _has_symbol(pw)
    score = (
        _length_score(length)
        + _char_class_count(pw)
        + _repeat_penalty(_count_consecutive_repeats(pw))
        + _symbol_bonus(length, has_symbol)
    )
    return max(score, 0)

