_CHAR_CHECKS = {
    "lower": lambda pw: any(ch.islower() for ch in pw),
    "upper": lambda pw: any(ch.isupper() for ch in pw),
    "digit": lambda pw: any(ch.isdigit() for ch in pw),
    "symbol": lambda pw: any(not ch.isalnum() for ch in pw),
}

_REPEAT_SCORES = {0: 0, 1: -1, 2: -1, 3: -2}


def _count_repeats(password: str) -> int:
    return sum(1 for i in range(1, len(password)) if password[i] == password[i - 1])


def _length_score(password: str) -> int:
    if len(password) >= 12:
        return 1
    if len(password) >= 8:
        return 1
    if len(password) < 4:
        return -1
    return 0


def _char_type_score(password: str) -> int:
    return sum(1 for check in _CHAR_CHECKS.values() if check(password))


def _repeat_penalty(repeats: int) -> int:
    return _REPEAT_SCORES.get(repeats, -2)


def _bonus_score(password: str) -> int:
    return 1 if len(password) >= 12 and _CHAR_CHECKS["symbol"](password) else 0


