export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

type Season = "low" | "high";

const VALID_SEASONS: readonly Season[] = ["low", "high"];

function isSeason(v: unknown): v is Season {
  return VALID_SEASONS.includes(v as Season);
}

function getInt(req: Record<string, unknown>, key: string): number | undefined {
  const val = req[key];
  return typeof val === "number" && Number.isInteger(val) ? val : undefined;
}

function validateCategory(
  req: Record<string, unknown>,
  category: string,
  limits: { nightsMin: number; nightsMax: number; guestsMin: number; guestsMax: number; minimumStay?: number },
  rates: { base: number; highSeasonSurcharge: number; extraGuestFee?: number; fixedFee?: number }
): QuoteResult {
  const loyaltyResult = validateLoyalty(req);
  if (!loyaltyResult.ok) return loyaltyResult;
  const nightsResult = validateNights(req, limits);
  if (!nightsResult.ok) return nightsResult;
  const guestsResult = validateGuests(req, limits);
  if (!guestsResult.ok) return guestsResult;
  const seasonResult = validateSeason(req);
  if (!seasonResult.ok) return seasonResult;

  return computeResult(req, category, nightsResult.total as number, guestsResult.total as number, loyaltyResult.total as number, rates);
}

function validateLoyalty(req: Record<string, unknown>): QuoteResult {
  const loyaltyYears = getInt(req, "loyaltyYears");
  if (loyaltyYears === undefined || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return { ok: true, total: loyaltyYears, policy: undefined, line: undefined };
}

function validateNights(req: Record<string, unknown>, limits: { nightsMin: number; nightsMax: number; minimumStay?: number }): QuoteResult {
  const nights = getInt(req, "nights");
  if (nights === undefined || nights < limits.nightsMin || nights > limits.nightsMax) {
    return { ok: false, error: "bad nights" };
  }
  const minimumStay = limits.minimumStay ?? 1;
  if (nights < minimumStay) {
    return { ok: false, error: "villa minimum stay" };
  }
  return { ok: true, total: nights, policy: undefined, line: undefined };
}

function validateGuests(req: Record<string, unknown>, limits: { guestsMin: number; guestsMax: number }): QuoteResult {
  const guests = getInt(req, "guests");
  if (guests === undefined || guests < limits.guestsMin || guests > limits.guestsMax) {
    return { ok: false, error: "bad guests" };
  }
  return { ok: true, total: guests, policy: undefined, line: undefined };
}

function validateSeason(req: Record<string, unknown>): QuoteResult {
  if (!isSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }
  return { ok: true, total: undefined as unknown as number, policy: undefined, line: undefined };
}

function computeResult(
  req: Record<string, unknown>,
  category: string,
  nights: number,
  guests: number,
  loyaltyYears: number,
  rates: { base: number; highSeasonSurcharge: number; extraGuestFee?: number; fixedFee?: number }
): QuoteResult {
  const { base, highSeasonSurcharge, extraGuestFee, fixedFee } = rates;
  const surcharge = (req.season === "high" ? highSeasonSurcharge : 0);
  let total = (base + surcharge) * nights;
  total = applyDiscount(req, total, loyaltyYears);
  total = applyExtraGuestFee(total, guests, extraGuestFee);
  total = applyFixedFee(total, fixedFee);
  const policy = determinePolicy(loyaltyYears, req.coupon);
  const line = `${category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

function applyDiscount(req: Record<string, unknown>, total: number, loyaltyYears: number): number {
  return (loyaltyYears >= 3 || req.coupon === "VIP")
    ? total - Math.floor(total / 10)
    : total;
}

function applyExtraGuestFee(total: number, guests: number, extraGuestFee?: number): number {
  return extraGuestFee !== undefined && guests > 2 ? total + extraGuestFee : total;
}

function applyFixedFee(total: number, fixedFee?: number): number {
  return fixedFee !== undefined ? total + fixedFee : total;
}

function determinePolicy(loyaltyYears: number, coupon: unknown): string {
  return (coupon === "VIP" || loyaltyYears >= 3) ? "flex" : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const category = req.category;
  if (typeof category !== "string") {
    return { ok: false, error: "unknown category" };
  }

  switch (category) {
    case "standard":
      return validateCategory(req, "standard",
        { nightsMin: 1, nightsMax: 14, guestsMin: 1, guestsMax: 2 },
        { base: 80, highSeasonSurcharge: 30 }
      );
    case "suite":
      return validateCategory(req, "suite",
        { nightsMin: 1, nightsMax: 21, guestsMin: 1, guestsMax: 4 },
        { base: 150, highSeasonSurcharge: 60, extraGuestFee: 25 }
      );
    case "villa":
      return validateCategory(req, "villa",
        { nightsMin: 1, nightsMax: 28, guestsMin: 1, guestsMax: 8, minimumStay: 3 },
        { base: 300, highSeasonSurcharge: 120, fixedFee: 500 }
      );
    default:
      return { ok: false, error: "unknown category" };
  }
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface BookingConfig {
  category: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highSurcharge: number;
  flatFee: number;
  extraGuestThreshold: number;
  extraGuestFee: number;
}

const BOOKING_CONFIGS: Record<string, BookingConfig> = {
  standard: {
    category: "standard",
    minNights: 1,
    maxNights: 14,
    minGuests: 1,
    maxGuests: 2,
    baseRate: 80,
    highSurcharge: 30,
    flatFee: 0,
    extraGuestThreshold: 2,
    extraGuestFee: 0,
  },
  suite: {
    category: "suite",
    minNights: 1,
    maxNights: 21,
    minGuests: 1,
    maxGuests: 4,
    baseRate: 150,
    highSurcharge: 60,
    flatFee: 0,
    extraGuestThreshold: 2,
    extraGuestFee: 25,
  },
  villa: {
    category: "villa",
    minNights: 1,
    maxNights: 28,
    minGuests: 1,
    maxGuests: 8,
    baseRate: 300,
    highSurcharge: 120,
    flatFee: 500,
    extraGuestThreshold: 0,
    extraGuestFee: 0,
  },
};

const DISCOUNT_THRESHOLD = 3;

function validateLoyalty(loyaltyYears: unknown): string | null {
  if (!Number.isInteger(loyaltyYears)) return "bad loyalty";
  if (loyaltyYears as number < 0) return "bad loyalty";
  return null;
}

function validateBooking(
  config: BookingConfig,
  nights: unknown,
  guests: unknown,
  season: unknown,
): string | null {
  if (!Number.isInteger(nights)) return "bad nights";
  const nightsNum = nights as number;
  if (nightsNum < config.minNights || nightsNum > config.maxNights) return "bad nights";

  if (config.category === "villa" && nightsNum < 3) return "villa minimum stay";

  if (!Number.isInteger(guests)) return "bad guests";
  const guestsNum = guests as number;
  if (guestsNum < config.minGuests || guestsNum > config.maxGuests) return "bad guests";

  if (season !== "low" && season !== "high") return "bad season";

  return null;
}

function calculateTotal(
  config: BookingConfig,
  nights: number,
  guests: number,
  season: string,
  loyaltyYears: number,
  coupon: string,
): number {
  let total = config.baseRate * nights;
  if (season === "high") total += config.highSurcharge * nights;
  if (coupon === "VIP" || loyaltyYears >= DISCOUNT_THRESHOLD)
    total -= Math.floor(total / 10);
  if (guests > config.extraGuestThreshold) total += config.extraGuestFee;
  total += config.flatFee;
  return total;
}

function determinePolicy(coupon: string, loyaltyYears: number): "strict" | "flex" {
  return coupon === "VIP" || loyaltyYears >= DISCOUNT_THRESHOLD ? "flex" : "strict";
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const loyaltyError = validateLoyalty(req.loyaltyYears);
  if (loyaltyError) return { ok: false, error: loyaltyError };

  const config = BOOKING_CONFIGS[req.category as string];
  if (!config) return { ok: false, error: "unknown category" };

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;
  const coupon = req.coupon as string;

  const bookingError = validateBooking(config, req.nights, req.guests, season);
  if (bookingError) return { ok: false, error: bookingError };

  const total = calculateTotal(config, nights, guests, season, loyaltyYears, coupon);
  const policy = determinePolicy(coupon, loyaltyYears);
  const line = `${config.category}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
