  const nights = req.nights;
  const guests = req.guests;
  const season = req.season as string | undefined;
  const coupon = req.coupon as string | undefined;

  switch (category) {
    case "standard": {
      if (!Number.isInteger(nights) || (nights as number) < 1 || (nights as number) > 14) {
        return { ok: false, error: "bad nights" };
      }
      if (!Number.isInteger(guests) || (guests as number) < 1 || (guests as number) > 2) {
        return { ok: false, error: "bad guests" };
      }
      if (season !== "low" && season !== "high") {
