      }
      if (g > 2) total += 25;
      let policy = "strict";
      if ((req.loyaltyYears as number) >= 3 || coupon === "VIP") {
        policy = "flex";
      }
      return { ok: true, total, policy, line: `suite:${n}n:${total}:${policy}` };
    }

    case "villa": {
      if (!Number.isInteger(nights) || (nights as number) < 1 || (nights as number) > 28) {
        return { ok: false, error: "bad nights" };
      }
      if ((nights as number) < 3) {
