      if (coupon === "VIP" || (req.loyaltyYears as number) >= 3) {
        policy = "flex";
      }
      return { ok: true, total, policy, line: `villa:${n}n:${total}:${policy}` };
    }

    default:
      return { ok: false, error: "unknown category" };
  }
}

export interface QuoteResult {
