    extraFee: 500,
  },
};

const VALID_SEASONS = new Set(["low", "high"]);

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value);
}

function validateLoyalty(req: Record<string, unknown>): QuoteResult | null {
  if (!isPositiveInteger(req.loyaltyYears) || (req.loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  return null;
}

function validateNights(req: Record<string, unknown>, config: BookingConfig): QuoteResult | null {
  if (!isPositiveInteger(req.nights)) {
    return { ok: false, error: "bad nights" };
  }
  const nights = req.nights as number;
  if (nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (config.villaMinNights && nights < config.villaMinNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  return null;
}

function validateGuests(req: Record<string, unknown>, config: BookingConfig): QuoteResult | null {
  if (!isPositiveInteger(req.guests)) {
    return { ok: false, error: "bad guests" };
  }
  const guests = req.guests as number;
  if (guests < config.minGuests || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  return null;
}

function validateSeason(req: Record<string, unknown>): QuoteResult | null {
  if (typeof req.season !== "string" || !VALID_SEASONS.has(req.season)) {
    return { ok: false, error: "bad season" };
  }
  return null;
}

function validateRequest(req: Record<string, unknown>, config: BookingConfig): QuoteResult | null {
  return (
    validateLoyalty(req) ??
    validateNights(req, config) ??
    validateGuests(req, config) ??
    validateSeason(req)
  );
}

function computeQuote(
  req: Record<string, unknown>,
  config: BookingConfig
): QuoteResult {
  const nights = req.nights as number;
  const guests = req.guests as number;
  const loyaltyYears = req.loyaltyYears as number;

  let total = config.baseRate * nights + (req.season === "high" ? config.seasonalPremium * nights : 0);
  if (loyaltyYears >= 3 || req.coupon === "VIP") {
    total -= Math.floor(total / 10);
  }
  if (guests > 2 && config.extraGuestFee > 0) {
    total += config.extraGuestFee;
  }
  total += config.extraFee;

  const policy = req.coupon === "VIP" || loyaltyYears >= 3 ? "flex" : "strict";
  const line = `${config.name}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const category = req.category as string;
  const config = CATEGORY_CONFIGS[category];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  const validationError = validateRequest(req, config);
  if (validationError) {
    return validationError;
  }

  return computeQuote(req, config);
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const config = lookupCategory((raw as Record<string, unknown>).category as string);
  if (config === undefined) {
    return { ok: false, error: "unknown category" };
  }

  const validate = (raw: unknown, config: BookingConfig): string | true => {
    const error = validateLoyalty((raw as Record<string, unknown>).loyaltyYears);
    if (error) return error;
    const errorNights = validateNights((raw as Record<string, unknown>).nights, config);
    if (errorNights) return errorNights;
    const errorGuests = validateGuests((raw as Record<string, unknown>).guests, config);
    if (errorGuests) return errorGuests;
    const errorSeason = validateSeason((raw as Record<string, unknown>).season);
    if (errorSeason) return errorSeason;
    return true;
  };

  const validation = validate(raw, config);
  if (validation !== true) {
    return { ok: false, error: validation };
  }

  const quote = buildQuote(raw, config);
  return quote;
}

interface BookingConfig {
  category: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  premiumRate: number;
  guestSurcharge: number;
  fixedFee: number;
  minStay: boolean;
}

function lookupCategory(category: string): BookingConfig | undefined {
  const configs: Record<string, BookingConfig> = {
    standard: {
      category: "standard",
      minNights: 1, maxNights: 14,
      minGuests: 1, maxGuests: 2,
      baseRate: 80, premiumRate: 30,
      guestSurcharge: 0, fixedFee: 0,
      minStay: false,
    },
    suite: {
      category: "suite",
      minNights: 1, maxNights: 21,
      minGuests: 1, maxGuests: 4,
      baseRate: 150, premiumRate: 60,
      guestSurcharge: 25, fixedFee: 0,
      minStay: false,
    },
    villa: {
      category: "villa",
      minNights: 1, maxNights: 28,
      minGuests: 1, maxGuests: 8,
      baseRate: 300, premiumRate: 120,
      guestSurcharge: 0, fixedFee: 500,
      minStay: true,
    },
  };
  return configs[category];
}

function validateLoyalty(value: unknown): string | true {
  if (!Number.isInteger(value) || (value as number) < 0) {
    return "bad loyalty";
  }
  return true;
}

function validateNights(value: unknown, config: BookingConfig): string | true {
  if (!Number.isInteger(value) || (value as number) < config.minNights || (value as number) > config.maxNights) {
    return "bad nights";
  }
  if (config.minStay && (value as number) < 3) {
    return "villa minimum stay";
  }
  return true;
}

function validateGuests(value: unknown, config: BookingConfig): string | true {
  if (!Number.isInteger(value) || (value as number) < config.minGuests || (value as number) > config.maxGuests) {
    return "bad guests";
  }
  return true;
}

function validateSeason(value: unknown): string | true {
  if (value !== "low" && value !== "high") {
    return "bad season";
  }
  return true;
}

function buildQuote(raw: unknown, config: BookingConfig): QuoteResult {
  const req = raw as Record<string, unknown>;
  const loyaltyYears = req.loyaltyYears as number;
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  const highSeasonPremium = season === "high" ? config.premiumRate * nights : 0;
  const discountEligible = loyaltyYears >= 3 || req.coupon === "VIP";
  let total = config.baseRate * nights + highSeasonPremium;

  if (discountEligible) {
    total -= Math.floor(total / 10);
  }

  if (guests > 2) {
    total += config.guestSurcharge;
  }
  total += config.fixedFee;

  const policy = discountEligible ? "flex" : "strict";
  const line = `${config.category}:${nights}n:${total}:${policy}`;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  const loyaltyYears = req.loyaltyYears as number;
  if (!Number.isInteger(loyaltyYears) || loyaltyYears < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const isVIP = req.coupon === "VIP";

  if (req.category === "standard") {
    return quoteCategory(req, loyaltyYears, isVIP, {
      minNights: 1,
      maxNights: 14,
      minGuests: 1,
      maxGuests: 2,
      baseRate: 80,
      highRate: 30,
      extraGuestCost: 0,
    });
  }

  if (req.category === "suite") {
    return quoteCategory(req, loyaltyYears, isVIP, {
      minNights: 1,
      maxNights: 21,
      minGuests: 1,
      maxGuests: 4,
      baseRate: 150,
      highRate: 60,
      extraGuestCost: 25,
    });
  }

  if (req.category === "villa") {
    return quoteCategory(req, loyaltyYears, isVIP, {
      minNights: 3,
      maxNights: 28,
      minGuests: 1,
      maxGuests: 8,
      baseRate: 300,
      highRate: 120,
      extraGuestCost: 0,
      minStaySurcharge: 500,
    });
  }

  return { ok: false, error: "unknown category" };
}

interface QuoteConfig {
  category: string;
  minNights: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  baseRate: number;
  highRate: number;
  extraGuestCost: number;
  minStaySurcharge?: number;
}

function validateNights(
  req: Record<string, unknown>,
  config: QuoteConfig
): QuoteResult | undefined {
  const nights = req.nights as number;
  if (!Number.isInteger(nights) || nights < config.minNights || nights > config.maxNights) {
    return { ok: false, error: "bad nights" };
  }
}

function validateGuests(
  req: Record<string, unknown>,
  config: QuoteConfig
): QuoteResult | undefined {
  const guests = req.guests as number;
  if (!Number.isInteger(guests) || guests < config.minGuests || guests > config.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
}

function validateSeason(req: Record<string, unknown>): QuoteResult | undefined {
  const season = req.season as string;
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
}

function validateRequest(
  req: Record<string, unknown>,
  config: QuoteConfig
): QuoteResult | undefined {
  const n = validateNights(req, config);
  if (n) return n;
  const g = validateGuests(req, config);
  if (g) return g;
  const s = validateSeason(req);
  if (s) return s;
}

function computeTotal(
  config: QuoteConfig,
  nights: number,
  guests: number,
  season: string,
  loyaltyYears: number,
  isVIP: boolean
): number {
  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highRate * nights;
  }
  if (loyaltyYears >= 3 || isVIP) {
    total -= Math.floor(total / 10);
  }
  if (guests > 2) {
    total += config.extraGuestCost;
  }
  if (config.minStaySurcharge) {
    total += config.minStaySurcharge;
  }
  return total;
}

function buildLine(config: QuoteConfig, nights: number, total: number, policy: string): string {
  return `${config.category}:${nights}n:${total}:${policy}`;
}

function quoteCategory(
  req: Record<string, unknown>,
  loyaltyYears: number,
  isVIP: boolean,
  config: QuoteConfig
): QuoteResult {
  const validation = validateRequest(req, config);
  if (validation) return validation;

  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  const total = computeTotal(config, nights, guests, season, loyaltyYears, isVIP);
  const policy = isVIP || loyaltyYears >= 3 ? "flex" : "strict";
  const line = buildLine(config, nights, total, policy);

  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

function isValidInteger(value: unknown, min?: number, max?: number): boolean {
  if (!Number.isInteger(value)) return false;
  if (min !== undefined && value < min) return false;
  if (max !== undefined && value > max) return false;
  return true;
}

function discount(coupon: unknown, loyaltyYears: number): boolean {
  return coupon === "VIP" || loyaltyYears >= 3;
}

function computeTotal(nights: number, baseRate: number, seasonalRate: number, highSeason: boolean, discount: boolean, extraGuestSurcharge?: number, flatFee?: number): number {
  let total = baseRate * nights + (highSeason ? seasonalRate * nights : 0);
  if (discount) total -= Math.floor(total / 10);
  if (extraGuestSurcharge !== undefined) total += extraGuestSurcharge;
  if (flatFee !== undefined) total += flatFee;
  return total;
}

interface CategoryConfig {
  minNights: number;
  maxNights: number;
  maxGuests: number;
  baseRate: number;
  seasonalRate: number;
  extraGuestSurcharge?: number;
  flatFee?: number;
}

const categoryConfig: Record<string, CategoryConfig> = {
  standard: { minNights: 1, maxNights: 14, maxGuests: 2, baseRate: 80, seasonalRate: 30 },
  suite: { minNights: 1, maxNights: 21, maxGuests: 4, baseRate: 150, seasonalRate: 60, extraGuestSurcharge: 25 },
  villa: { minNights: 3, maxNights: 28, maxGuests: 8, baseRate: 300, seasonalRate: 120, flatFee: 500 },
};

function buildQuote(category: string, nights: number, guests: number, season: unknown, loyaltyYears: number, coupon: unknown, config: CategoryConfig): QuoteResult {
  if (!isValidInteger(guests, 1, config.maxGuests) || season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }
  if (!isValidInteger(nights, config.minNights, config.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  const applyDiscount = discount(coupon, loyaltyYears);
  const flex = discount(coupon, loyaltyYears);
  const total = computeTotal(nights, config.baseRate, config.seasonalRate, season === "high", applyDiscount, config.extraGuestSurcharge, config.flatFee);
  return { ok: true, total, policy: flex ? "flex" : "strict", line: `${category}:${nights}n:${total}:${flex ? "flex" : "strict"}` };
}

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;

  if (!isValidInteger(req.loyaltyYears, 0)) {
    return { ok: false, error: "bad loyalty" };
  }

  const category = req.category as string;
  const config = categoryConfig[category];
  if (!config) {
    return { ok: false, error: "unknown category" };
  }

  if (!Number.isInteger(req.nights) || !Number.isInteger(req.guests)) {
    return { ok: false, error: "bad nights" };
  }

  return buildQuote(
    category,
    req.nights as number,
    req.guests as number,
    req.season,
    req.loyaltyYears as number,
    req.coupon,
    config,
  );
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryConfig {
  name: string;
  baseRate: number;
  highSurcharge: number;
  maxNights: number;
  minGuests: number;
  maxGuests: number;
  extraGuestFee?: (guests: number) => number;
  fixedFee?: number;
  minNights: number;
  minStayNights?: number;
  minStayError?: string;
}

const configs: Record<string, CategoryConfig> = {
  standard: {
    name: "standard",
    baseRate: 80,
    highSurcharge: 30,
    maxNights: 14,
    minNights: 1,
    minGuests: 1,
    maxGuests: 2,
  },
  suite: {
    name: "suite",
    baseRate: 150,
    highSurcharge: 60,
    maxNights: 21,
    minNights: 1,
    minGuests: 1,
    maxGuests: 4,
    extraGuestFee: () => 25,
  },
  villa: {
    name: "villa",
    baseRate: 300,
    highSurcharge: 120,
    maxNights: 28,
    minNights: 1,
    minGuests: 1,
    maxGuests: 8,
    extraGuestFee: () => 25,
    fixedFee: 500,
    minStayNights: 3,
    minStayError: "villa minimum stay",
  },
};

function isValidSeason(season: unknown): boolean {
  return season === "low" || season === "high";
}

function isIntegerInRange(value: unknown, min: number, max: number): boolean {
  return Number.isInteger(value) && value >= min && value <= max;
}

function computeTotal(config: CategoryConfig, nights: number, season: string, loyalty: number, coupon: string, guests: number): number {
  let total = config.baseRate * nights;
  if (season === "high") {
    total += config.highSurcharge * nights;
  }
  if (loyalty >= 3 || coupon === "VIP") {
    total -= Math.floor(total / 10);
  }
  if (config.extraGuestFee && guests > 2) {
    total += config.extraGuestFee(guests);
  }
  if (config.fixedFee) {
    total += config.fixedFee;
  }
  return total;
}

function determinePolicy(loyalty: number, coupon: string): string {
  return coupon === "VIP" || loyalty >= 3 ? "flex" : "strict";
}

function validateAndQuote(config: CategoryConfig, req: Record<string, unknown>, loyalty: number): QuoteResult {
  if (!isIntegerInRange(req.nights, config.minNights, config.maxNights)) {
    return { ok: false, error: "bad nights" };
  }
  if (config.minStayNights && (req.nights as number) < config.minStayNights) {
    return { ok: false, error: config.minStayError ?? "bad nights" };
  }
  if (!isIntegerInRange(req.guests, config.minGuests, config.maxGuests)) {
    return { ok: false, error: "bad guests" };
  }
  if (!isValidSeason(req.season)) {
    return { ok: false, error: "bad season" };
  }

  const nights = req.nights as number;
  const season = req.season as string;
  const coupon = req.coupon as string;
  const guests = req.guests as number;

  const total = computeTotal(config, nights, season, loyalty, coupon, guests);
  const policy = determinePolicy(loyalty, coupon);
  const line = `${config.name}:${nights}n:${total}:${policy}`;

  return { ok: true, total, policy, line };
}

const quoteHandlers: Record<string, (req: Record<string, unknown>, loyalty: number) => QuoteResult> = {
  standard: (req, loyalty) => validateAndQuote(configs.standard, req, loyalty),
  suite: (req, loyalty) => validateAndQuote(configs.suite, req, loyalty),
  villa: (req, loyalty) => validateAndQuote(configs.villa, req, loyalty),
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }

  const req = raw as Record<string, unknown>;
  const loyaltyYears = req.loyaltyYears;
  if (!Number.isInteger(loyaltyYears) || (loyaltyYears as number) < 0) {
    return { ok: false, error: "bad loyalty" };
  }
  const loyalty = loyaltyYears as number;

  const category = req.category as string;
  const handler = quoteHandlers[category];
  if (!handler) {
    return { ok: false, error: "unknown category" };
  }

  return handler(req, loyalty);
}

