export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

interface RouteConfig {
  action: string;
  dataKey: string;
  defaultStatus?: string;
}

const EVENT_ROUTES: Record<string, RouteConfig> = {
  "user.created":  { action: "created user",       dataKey: "id" },
  "user.updated":  { action: "updated user",       dataKey: "id" },
  "user.deleted":  { action: "deleted user",       dataKey: "id" },
  "order.placed":  { action: "order placed",       dataKey: "orderId" },
  "order.cancelled": { action: "order cancelled",  dataKey: "orderId" },
  "order.shipped": { action: "order shipped",      dataKey: "orderId" },
  "payment.succeeded": { action: "payment succeeded", dataKey: "paymentId" },
  "payment.failed":  { action: "payment failed",   dataKey: "paymentId", defaultStatus: "error" },
  "invoice.issued":  { action: "invoice issued",   dataKey: "invoiceId" },
  "invoice.voided":  { action: "invoice voided",   dataKey: "invoiceId" },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = EVENT_ROUTES[name];
  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  const value = String(payload.data[config.dataKey]);
  return {
    status: config.defaultStatus ?? "ok",
    message: `${config.action} ${value}`,
  };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

type EventRoute = {
  template: string;
  idField: string;
  defaultStatus: string;
};

const EVENT_ROUTES: Record<string, EventRoute> = {
  "user.created":   { template: "created user {id}",  idField: "id",         defaultStatus: "ok" },
  "user.updated":   { template: "updated user {id}",  idField: "id",         defaultStatus: "ok" },
  "user.deleted":   { template: "deleted user {id}",  idField: "id",         defaultStatus: "ok" },
  "order.placed":   { template: "order placed {id}",  idField: "orderId",    defaultStatus: "ok" },
  "order.cancelled":{ template: "order cancelled {id}",idField: "orderId",   defaultStatus: "ok" },
  "order.shipped":  { template: "order shipped {id}", idField: "orderId",    defaultStatus: "ok" },
  "payment.succeeded":{ template: "payment succeeded {id}",idField: "paymentId", defaultStatus: "ok" },
  "payment.failed": { template: "payment failed {id}",idField: "paymentId",  defaultStatus: "error" },
  "invoice.issued": { template: "invoice issued {id}",idField: "invoiceId",  defaultStatus: "ok" },
  "invoice.voided": { template: "invoice voided {id}",idField: "invoiceId",  defaultStatus: "ok" },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const route = EVENT_ROUTES[name];
  if (route) {
    const id = String(payload.data[route.idField as keyof typeof payload.data] ?? "");
    return { status: route.defaultStatus, message: route.template.replace("{id}", id) };
  }
  return { status: "error", message: `unknown event: ${name}` };
}

export interface EventPayload {
  data: Record<string, unknown>;
}

export interface EventResult {
  status: string;
  message: string;
}

const EVENT_HANDLERS: Record<
  string,
  { status: string; field: string; template: (fieldValue: string) => string }
> = {
  "user.created":     { status: "ok", field: "id",              template: (v) => `created user ${v}` },
  "user.updated":     { status: "ok", field: "id",              template: (v) => `updated user ${v}` },
  "user.deleted":     { status: "ok", field: "id",              template: (v) => `deleted user ${v}` },
  "order.placed":     { status: "ok", field: "orderId",         template: (v) => `order placed ${v}` },
  "order.cancelled":  { status: "ok", field: "orderId",         template: (v) => `order cancelled ${v}` },
  "order.shipped":    { status: "ok", field: "orderId",         template: (v) => `order shipped ${v}` },
  "payment.succeeded":{ status: "ok", field: "paymentId",       template: (v) => `payment succeeded ${v}` },
  "payment.failed":   { status: "error", field: "paymentId",    template: (v) => `payment failed ${v}` },
  "invoice.issued":   { status: "ok", field: "invoiceId",       template: (v) => `invoice issued ${v}` },
  "invoice.voided":   { status: "ok", field: "invoiceId",       template: (v) => `invoice voided ${v}` },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const handler = EVENT_HANDLERS[name];
  if (!handler) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  const fieldValue = String(payload.data[handler.field]);
  return { status: handler.status, message: handler.template(fieldValue) };
