  message: string;
}

interface EventConfig {
  template: string;
  idKey: string;
  status: string;
}

const EVENT_HANDLERS: Record<string, EventConfig> = {
  "user.created":    { template: "created %s", idKey: "id",         status: "ok" },
  "user.updated":    { template: "updated %s", idKey: "id",         status: "ok" },
  "user.deleted":    { template: "deleted %s", idKey: "id",         status: "ok" },
  "order.placed":    { template: "order placed %s", idKey: "orderId",  status: "ok" },
  "order.cancelled": { template: "order cancelled %s", idKey: "orderId", status: "ok" },
  "order.shipped":   { template: "order shipped %s", idKey: "orderId",  status: "ok" },
