  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function nextArg(argv: string[], i: number): { value: string; index: number } {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error("missing required argument");
  }
  return { value, index: i + 1 };
}

function parseIntArg(argv: string[], i: number, flagName: string): { value: number; index: number } {
  const raw = argv[i + 1];
  if (raw === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  const value = Number(raw);
  if (!Number.isInteger(value)) {
    throw new Error(`${flagName} must be an integer`);
  }
  return { value, index: i + 1 };
}

type Handler = (config: FlagConfig, argv: string[], i: number) => number;

const HANDLERS: Record<string, Handler> = {
  "--verbose": (config) => {
    config.verbose = true;
    return 0;
  },
  "--quiet": (config) => {
    config.quiet = true;
    return 0;
  },
  "--dry-run": (config) => {
    config.dryRun = true;
    return 0;
  },
  "--force": (config) => {
    config.force = true;
    return 0;
  },
  "--no-color": (config) => {
    config.color = false;
    return 0;
  },
  "--strict": (config) => {
    config.strict = true;
    return 0;
  },
  "--output": (config, argv, i) => {
    const { value } = nextArg(argv, i);
    config.outputPath = value;
    return 1;
  },
  "--config": (config, argv, i) => {
    const { value } = nextArg(argv, i);
    config.configPath = value;
    return 1;
  },
  "--format": (config, argv, i) => {
    const { value } = nextArg(argv, i);
    if (!VALID_FORMATS.includes(value as typeof VALID_FORMATS[number])) {
      throw new Error(`unsupported format: ${value}`);
    }
    config.format = value;
    return 1;
  },
  "--log-level": (config, argv, i) => {
    const { value } = nextArg(argv, i);
    if (!VALID_LOG_LEVELS.includes(value as typeof VALID_LOG_LEVELS[number])) {
      throw new Error(`unsupported log level: ${value}`);
    }
    config.logLevel = value;
    return 1;
  },
  "--retries": (config, argv, i) => {
    const { value } = parseIntArg(argv, i, "--retries");
    config.maxRetries = value;
    return 1;
  },
  "--timeout": (config, argv, i) => {
    const { value } = parseIntArg(argv, i, "--timeout");
    config.timeoutMs = value;
    return 1;
  },
  "--parallel": (config, argv, i) => {
    const { value } = parseIntArg(argv, i, "--parallel");
    config.parallelism = value;
    return 1;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = HANDLERS[arg];
    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i += handler(config, argv, i);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
