const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

const FLAG_HANDLERS: Record<
  string,
  { requiresValue?: true; handler: (config: FlagConfig, value: string) => void }
> = {
  "--verbose": { handler: (config) => { config.verbose = true; } },
  "--quiet": { handler: (config) => { config.quiet = true; } },
  "--dry-run": { handler: (config) => { config.dryRun = true; } },
  "--force": { handler: (config) => { config.force = true; } },
