      if (!Number.isInteger(parsed)) {
        throw new Error("--timeout must be an integer");
      }
      config.timeoutMs = parsed;
    },
  },
  "--parallel": {
    requiresValue: true,
    handler: (config, value) => {
      const parsed = Number(value);
      if (!Number.isInteger(parsed)) {
        throw new Error("--parallel must be an integer");
      }
      config.parallelism = parsed;
    },
  },
};

function normalizeFlag(arg: string): string {
