    const arg = normalizeFlag(raw);

    const flagHandler = FLAG_HANDLERS[arg];
    if (!flagHandler) {
      throw new Error(`unknown flag: "${raw}"`);
    }

    if (flagHandler.requiresValue) {
      const next = argv[++i];
      if (next === undefined) {
        throw new Error(`${raw} requires a value`);
      }
      flagHandler.handler(config, next);
    } else {
      flagHandler.handler(config);
    }
  }

  return config;
}

export interface FlagConfig {
