export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
  "--no-color": "--color",
};

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function consumeValue(argv: string[], i: number): string {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error("missing value for flag");
  }
  return value;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function applyVerbose(config: FlagConfig, _argv: string[], idx: number): number {
  config.verbose = true;
  return idx + 1;
}

function applyQuiet(config: FlagConfig, _argv: string[], idx: number): number {
  config.quiet = true;
  return idx + 1;
}

function applyDryRun(config: FlagConfig, _argv: string[], idx: number): number {
  config.dryRun = true;
  return idx + 1;
}

function applyForce(config: FlagConfig, _argv: string[], idx: number): number {
  config.force = true;
  return idx + 1;
}

function applyStrict(config: FlagConfig, _argv: string[], idx: number): number {
  config.strict = true;
  return idx + 1;
}

const BOOLEAN_RESOLVER: Record<string, (config: FlagConfig, argv: string[], idx: number) => number> = {
  "--verbose": applyVerbose,
  "-v": applyVerbose,
  "--quiet": applyQuiet,
  "-q": applyQuiet,
  "--dry-run": applyDryRun,
  "--force": applyForce,
  "-f": applyForce,
  "--strict": applyStrict,
};

function applyOutput(config: FlagConfig, argv: string[], idx: number): number {
  config.outputPath = consumeValue(argv, idx);
  return idx + 2;
}

function applyConfig(config: FlagConfig, argv: string[], idx: number): number {
  config.configPath = consumeValue(argv, idx);
  return idx + 2;
}

function applyColor(config: FlagConfig, argv: string[], idx: number): number {
  const value = consumeValue(argv, idx);
  if (value === "false") {
    config.color = false;
  } else if (value !== "true") {
    throw new Error(`--color accepts true or false, got: ${value}`);
  }
  return idx + 2;
}

function applyFormat(config: FlagConfig, argv: string[], idx: number): number {
  const value = consumeValue(argv, idx);
  if ((VALID_FORMATS as readonly string[]).includes(value)) {
    config.format = value;
  } else {
    throw new Error(`unsupported format: ${value}`);
  }
  return idx + 2;
}

function applyLogLevel(config: FlagConfig, argv: string[], idx: number): number {
  const value = consumeValue(argv, idx);
  if ((VALID_LOG_LEVELS as readonly string[]).includes(value)) {
    config.logLevel = value;
  } else {
    throw new Error(`unsupported log level: ${value}`);
  }
  return idx + 2;
}

function applyRetries(config: FlagConfig, argv: string[], idx: number): number {
  const raw = consumeValue(argv, idx);
  const value = Number(raw);
  if (Number.isInteger(value) && value >= 0) {
    config.maxRetries = value;
  } else {
    throw new Error(`--retries must be a non-negative integer, got: ${raw}`);
  }
  return idx + 2;
}

function applyTimeout(config: FlagConfig, argv: string[], idx: number): number {
  const raw = consumeValue(argv, idx);
  const value = Number(raw);
  if (Number.isInteger(value) && value > 0) {
    config.timeoutMs = value;
  } else {
    throw new Error(`--timeout must be a positive integer, got: ${raw}`);
  }
  return idx + 2;
}

function applyParallel(config: FlagConfig, argv: string[], idx: number): number {
  const raw = consumeValue(argv, idx);
  const value = Number(raw);
  if (Number.isInteger(value) && value > 0) {
    config.parallelism = value;
  } else {
    throw new Error(`--parallel must be a positive integer, got: ${raw}`);
  }
  return idx + 2;
}

const STRING_RESOLVERS: Record<string, (config: FlagConfig, argv: string[], idx: number) => number> = {
  "--output": applyOutput,
  "-o": applyOutput,
  "--config": applyConfig,
  "--color": applyColor,
  "--format": applyFormat,
  "--log-level": applyLogLevel,
};

const NUMBER_RESOLVERS: Record<string, (config: FlagConfig, argv: string[], idx: number) => number> = {
  "--retries": applyRetries,
  "--timeout": applyTimeout,
  "--parallel": applyParallel,
};

function resolve(argv: string[], idx: number): (config: FlagConfig, argv: string[], idx: number) => number {
  const flag = normalizeFlag(argv[idx]!);

  if (flag in BOOLEAN_RESOLVER) {
    return BOOLEAN_RESOLVER[flag];
  }

  if (flag in STRING_RESOLVERS) {
    return STRING_RESOLVERS[flag];
  }

  if (flag in NUMBER_RESOLVERS) {
    return NUMBER_RESOLVERS[flag];
  }

  throw new Error(`unknown flag: ${flag}`);
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; ) {
    const resolver = resolve(argv, i);
    i = resolver(config, argv, i);
  }

  return config;
}

