  color: true,
  strict: false,
};

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

type FlagAction = (config: FlagConfig, value: string | undefined) => void;

interface FlagEntry {
  takesValue: boolean;
  action: FlagAction;
}

function parseInteger(flagName: string, value: string | undefined): number {
  if (value === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  const result = Number(value);
  if (!Number.isInteger(result)) {
    throw new Error(`${flagName} must be an integer`);
  }
  return result;
}

const FLAG_ENTRIES: Record<string, FlagEntry> = {
  "--verbose": {
    takesValue: false,
    action: (config) => { config.verbose = true; },
  },
  "--quiet": {
    takesValue: false,
    action: (config) => { config.quiet = true; },
  },
  "--dry-run": {
    takesValue: false,
    action: (config) => { config.dryRun = true; },
  },
  "--force": {
    takesValue: false,
    action: (config) => { config.force = true; },
  },
  "--no-color": {
    takesValue: false,
    action: (config) => { config.color = false; },
  },
  "--strict": {
    takesValue: false,
    action: (config) => { config.strict = true; },
  },
  "--output": {
    takesValue: true,
    action: (config, value) => {
      if (value === undefined) {
        throw new Error("--output requires a path");
      }
      config.outputPath = value;
    },
  },
  "--config": {
    takesValue: true,
    action: (config, value) => {
      if (value === undefined) {
        throw new Error("--config requires a path");
      }
      config.configPath = value;
    },
  },
  "--format": {
    takesValue: true,
    action: (config, value) => {
      if (value === undefined) {
        throw new Error("--format requires a value (json, yaml, or text)");
      }
      if (!VALID_FORMATS.includes(value)) {
        throw new Error(`unsupported format: ${value}`);
      }
      config.format = value;
    },
  },
  "--log-level": {
    takesValue: true,
    action: (config, value) => {
      if (value === undefined) {
        throw new Error("--log-level requires a value (debug, info, warn, or error)");
      }
      if (!VALID_LOG_LEVELS.includes(value)) {
        throw new Error(`unsupported log level: ${value}`);
      }
      config.logLevel = value;
    },
  },
  "--retries": {
    takesValue: true,
    action: (config, value) => {
      config.maxRetries = parseInteger("--retries", value);
    },
  },
  "--timeout": {
    takesValue: true,
    action: (config, value) => {
      config.timeoutMs = parseInteger("--timeout", value);
    },
  },
  "--parallel": {
    takesValue: true,
    action: (config, value) => {
      config.parallelism = parseInteger("--parallel", value);
    },
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = { ...DEFAULT_CONFIG };

  for (let i = 0; i < argv.length; i++) {
    const rawArg = argv[i]!;
    const normalized = normalizeFlag(rawArg);
    const entry = FLAG_ENTRIES[normalized];

    if (entry === undefined) {
      throw new Error(`unknown flag: ${rawArg}`);
    }

    const value = entry.takesValue ? argv[++i] : undefined;
    entry.action(config, value);
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function expectValue(argv: string[], i: number, flagName: string): string {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  return value;
}

const NUMBER_FLAG_RE = /^-?\d+$/;

function parseInteger(argv: string[], i: number, flagName: string): number {
  const value = argv[i + 1];
  if (value === undefined || !NUMBER_FLAG_RE.test(value)) {
    throw new Error(`${flagName} must be an integer`);
  }
  return Number(value);
}

const FORMAT_OPTIONS = new Set(["json", "yaml", "text"]);
const LOG_LEVEL_OPTIONS = new Set(["debug", "info", "warn", "error"]);

type FlagHandler = (value: string | undefined, index: number) => void;

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": () => { config.verbose = true; },
  "--quiet": () => { config.quiet = true; },
  "--dry-run": () => { config.dryRun = true; },
  "--force": () => { config.force = true; },
  "--no-color": () => { config.color = false; },
  "--strict": () => { config.strict = true; },
  "--output": (_, i) => { config.outputPath = expectValue(argv, i, "--output"); },
  "--config": (_, i) => { config.configPath = expectValue(argv, i, "--config"); },
  "--format": (_, i) => {
    const value = expectValue(argv, i, "--format");
    if (!FORMAT_OPTIONS.has(value)) {
      throw new Error(`unsupported format: ${value}`);
    }
    config.format = value;
  },
  "--log-level": (_, i) => {
    const value = expectValue(argv, i, "--log-level");
    if (!LOG_LEVEL_OPTIONS.has(value)) {
      throw new Error(`unsupported log level: ${value}`);
    }
    config.logLevel = value;
  },
  "--retries": (_, i) => { config.maxRetries = parseInteger(argv, i, "--retries"); },
  "--timeout": (_, i) => { config.timeoutMs = parseInteger(argv, i, "--timeout"); },
  "--parallel": (_, i) => { config.parallelism = parseInteger(argv, i, "--parallel"); },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const handler = FLAG_HANDLERS[arg];
    if (handler) {
      handler(undefined, i);
      i++;
    } else {
      throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function isFlag(arg: string): boolean {
  return arg.startsWith("-");
}

function consumeValue(argv: string[], i: number, flagName: string): [string, number] {
  const value = argv[i + 1];
  if (value === undefined) {
    throw new Error(`${flagName} requires a value`);
  }
  return [value, i + 1];
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const rawArg = argv[i]!;

    if (!isFlag(rawArg)) {
      throw new Error(`unknown flag: ${rawArg}`);
    }

    const arg = normalizeFlag(rawArg);
    const entry = FLAG_DEFINITIONS[arg];

    if (!entry) {
      throw new Error(`unknown flag: ${arg}`);
    }

    if (entry.takesValue) {
      const [value, nextIndex] = consumeValue(argv, i, arg);
      const error = entry.validate(value);
      if (error) {
        throw new Error(error);
      }
      entry.set(config, value);
      i = nextIndex;
    } else {
      entry.set(config);
    }
  }

  return config;
}

interface FlagDefinition {
  set: (config: FlagConfig, value?: string) => void;
  takesValue: boolean;
  validate?: (value: string) => string | undefined;
}

const FLAG_DEFINITIONS: Record<string, FlagDefinition> = {
  "--verbose": {
    set: (c) => { c.verbose = true; },
    takesValue: false,
  },
  "--quiet": {
    set: (c) => { c.quiet = true; },
    takesValue: false,
  },
  "--dry-run": {
    set: (c) => { c.dryRun = true; },
    takesValue: false,
  },
  "--force": {
    set: (c) => { c.force = true; },
    takesValue: false,
  },
  "--no-color": {
    set: (c) => { c.color = false; },
    takesValue: false,
  },
  "--strict": {
    set: (c) => { c.strict = true; },
    takesValue: false,
  },
  "--output": {
    set: (c, v) => { c.outputPath = v!; },
    takesValue: true,
  },
  "--config": {
    set: (c, v) => { c.configPath = v!; },
    takesValue: true,
  },
  "--format": {
    set: (c, v) => { c.format = v!; },
    takesValue: true,
    validate: (v) => {
      if (!["json", "yaml", "text"].includes(v)) {
        return `unsupported format: ${v}`;
      }
      return undefined;
    },
  },
  "--log-level": {
    set: (c, v) => { c.logLevel = v!; },
    takesValue: true,
    validate: (v) => {
      if (!["debug", "info", "warn", "error"].includes(v)) {
        return `unsupported log level: ${v}`;
      }
      return undefined;
    },
  },
  "--retries": {
    set: (c, v) => { c.maxRetries = Number(v!); },
    takesValue: true,
    validate: (v) => {
      const num = Number(v);
      if (!Number.isInteger(num)) {
        return "--retries must be an integer";
      }
      return undefined;
    },
  },
  "--timeout": {
    set: (c, v) => { c.timeoutMs = Number(v!); },
    takesValue: true,
    validate: (v) => {
      const num = Number(v);
      if (!Number.isInteger(num)) {
        return "--timeout must be an integer";
      }
      return undefined;
    },
  },
  "--parallel": {
    set: (c, v) => { c.parallelism = Number(v!); },
    takesValue: true,
    validate: (v) => {
      const num = Number(v);
      if (!Number.isInteger(num)) {
        return "--parallel must be an integer";
      }
      return undefined;
    },
  },
};

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function normalizeFlag(arg: string): string {
  if (!arg.startsWith("-") || arg === "-") {
    return arg;
  }
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function parsePositiveInt(value: string, flag: string): number {
  const num = Number(value);
  if (!Number.isInteger(num)) {
    throw new Error(`${flag} must be an integer`);
  }
  if (num < 0) {
    throw new Error(`${flag} must be a non-negative integer`);
  }
  return num;
}

type FlagHandler = (config: FlagConfig, value: string | undefined) => void;

function makeHandler(flag: string, setter: (config: FlagConfig, value: string) => void): FlagHandler {
  return (config: FlagConfig, value: string | undefined) => {
    if (value === undefined) {
      throw new Error(`${flag} requires a value`);
    }
    setter(config, value);
  };
}

function makeValidatedHandler(
  flag: string,
  validator: (value: string) => void,
  setter: (config: FlagConfig, value: string) => void,
): FlagHandler {
  return (config: FlagConfig, value: string | undefined) => {
    if (value === undefined) {
      throw new Error(`${flag} requires a value`);
    }
    validator(value);
    setter(config, value);
  };
}

function makeParseIntHandler(
  flag: string,
  setConfig: (config: FlagConfig, num: number) => void,
): FlagHandler {
  return (config: FlagConfig, value: string | undefined) => {
    if (value === undefined) {
      throw new Error(`${flag} requires an integer value`);
    }
    const num = parsePositiveInt(value, flag);
    setConfig(config, num);
  };
}

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": (config) => { config.verbose = true; },
  "--quiet": (config) => { config.quiet = true; },
  "--dry-run": (config) => { config.dryRun = true; },
  "--force": (config) => { config.force = true; },
  "--no-color": (config) => { config.color = false; },
  "--strict": (config) => { config.strict = true; },
  "--output": makeHandler("--output", (config, value) => { config.outputPath = value; }),
  "--config": makeHandler("--config", (config, value) => { config.configPath = value; }),
  "--format": makeValidatedHandler(
    "--format",
    (value) => {
      if (!VALID_FORMATS.includes(value as typeof VALID_FORMATS[number])) {
        throw new Error(`unsupported format: ${value}`);
      }
    },
    (config, value) => { config.format = value; },
  ),
  "--log-level": makeValidatedHandler(
    "--log-level",
    (value) => {
      if (!VALID_LOG_LEVELS.includes(value as typeof VALID_LOG_LEVELS[number])) {
        throw new Error(`unsupported log level: ${value}`);
      }
    },
    (config, value) => { config.logLevel = value; },
  ),
  "--retries": makeParseIntHandler("--retries", (config, num) => { config.maxRetries = num; }),
  "--timeout": makeParseIntHandler("--timeout", (config, num) => { config.timeoutMs = num; }),
  "--parallel": makeParseIntHandler("--parallel", (config, num) => { config.parallelism = num; }),
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();
  let i = 0;

  while (i < argv.length) {
    const arg = normalizeFlag(argv[i]!);
    const handler = FLAG_HANDLERS[arg];
    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }
    handler(config, argv[++i]);
    i++;
  }

  return config;
}

