export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_BOUNDARIES: [number, string][] = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
];

export function gradeReport(record: StudentRecord): GradeReport {
  let letter = "F";
  for (const [minScore, grade] of GRADE_BOUNDARIES) {
    if (record.score >= minScore) {
      letter = grade;
      break;
    }
  }

  let modifier = "none";

  if (record.absences > 20) {
    letter = "F";
    modifier = "attendance-failure";
  } else if (record.extraCredit >= 5 && record.score >= 90) {
    modifier = "honors";
  }

  return { letter, modifier };
}

