interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1;
}

type Context = {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: { value: number };
};

type Handler = (index: number, event: Record<string, unknown>, ctx: Context) => FulfillmentResult | undefined;

function handleOrder(index: number, event: Record<string, unknown>, ctx: Context): FulfillmentResult | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const orderId = event.id;
  if (ctx.orders[orderId] !== undefined) {
    return { ok: false, error: "event " + index + ": duplicate order" };
  }
  if (typeof event.item !== "string" || event.item.length === 0) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  if (!isPositiveInteger(event.qty)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const qty = event.qty as number;
  const item = event.item;
  const available = ctx.stock[item] ?? 0;
  if (available >= qty) {
    ctx.stock[item] = available - qty;
    ctx.reserved[orderId] = { item, qty };
    ctx.orders[orderId] = "reserved";
  } else {
    ctx.queue.push(orderId);
    ctx.pendingWants[orderId] = { item, qty };
    ctx.orders[orderId] = "backordered";
  }
  return undefined;
}

function handleCancel(index: number, event: Record<string, unknown>, ctx: Context): FulfillmentResult | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const orderId = event.id;
  if (ctx.reserved[orderId] !== undefined) {
    handleRelease(orderId, ctx);
    ctx.orders[orderId] = "cancelled";
    tryFulfillPending(ctx);
  } else if (ctx.orders[orderId] === "backordered") {
    const idx = ctx.queue.indexOf(orderId);
    if (idx !== -1) ctx.queue.splice(idx, 1);
    delete ctx.pendingWants[orderId];
    ctx.orders[orderId] = "cancelled";
  } else {
    ctx.rejected.value++;
  }
  return undefined;
}

function handleShip(index: number, event: Record<string, unknown>, ctx: Context): FulfillmentResult | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const orderId = event.id;
  if (event.qty !== undefined && (!isPositiveInteger(event.qty) || event.qty < 1)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  if (ctx.reserved[orderId] === undefined) {
    ctx.rejected.value++;
  } else if (event.qty === undefined || event.qty === ctx.reserved[orderId].qty) {
    delete ctx.reserved[orderId];
    ctx.orders[orderId] = "shipped";
  } else if (event.qty < ctx.reserved[orderId].qty) {
    ctx.reserved[orderId].qty -= event.qty as number;
    ctx.orders[orderId] = "partial";
  } else {
    ctx.rejected.value++;
  }
  return undefined;
}

function handleRestock(index: number, event: Record<string, unknown>, ctx: Context): FulfillmentResult | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  if (!isPositiveInteger(event.qty)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const item = event.item;
  const qty = event.qty as number;
  ctx.stock[item] = (ctx.stock[item] ?? 0) + qty;
  tryFulfillPending(ctx);
  return undefined;
}

function handleExpire(index: number, event: Record<string, unknown>, ctx: Context): FulfillmentResult | undefined {
  if (typeof event.id !== "string" || event.id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const orderId = event.id;
  if (ctx.reserved[orderId] !== undefined) {
    handleRelease(orderId, ctx);
    ctx.orders[orderId] = "expired";
    tryFulfillPending(ctx);
  } else {
    ctx.rejected.value++;
  }
  return undefined;
}

function handleRelease(orderId: string, ctx: Context): void {
  const holding = ctx.reserved[orderId];
  ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
  delete ctx.reserved[orderId];
}

function tryFulfillPending(ctx: Context): void {
  for (let i = ctx.queue.length - 1; i >= 0; i--) {
    const pendingId = ctx.queue[i];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(i, 1);
    }
  }
}

const handlers: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInteger(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item];
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  const rejected = { value: 0 };

  const ctx: Context = { stock, orders, reserved, pendingWants, queue, rejected };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const type = event.type as string;
    const handler = handlers[type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const result = handler(index, event, ctx);
    if (result !== undefined) {
      return result;
    }
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected: rejected.value,
    report: buildReport(orders, rejected.value),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function parseInput(raw: unknown): { ok: boolean; error?: FulfillmentResult; stock?: Record<string, number>; events?: unknown[] } {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: { ok: false, error: "malformed input" } };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: { ok: false, error: "bad stock" } };
  }
  const stock: Record<string, number> = {};
  for (const item of Object.keys(input.stock as Record<string, unknown>)) {
    const val = (input.stock as Record<string, unknown>)[item];
    if (typeof val !== "number" || !Number.isInteger(val) || val < 0) {
      return { ok: false, error: { ok: false, error: "bad stock" } };
    }
    stock[item] = val;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: { ok: false, error: "bad events" } };
  }
  return { ok: true, stock, events: input.events };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const input = parseInput(raw);
  if (!input.ok) return input.error!;
  const { stock, events } = input;

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  function safeInt(event: Record<string, unknown>, key: string): number | undefined {
    const val = event[key];
    if (typeof val === "number" && Number.isInteger(val)) return val;
    return undefined;
  }

  function tryFillQueue() {
    let i = 0;
    while (i < queue.length) {
      const pendingId = queue[i];
      const want = pendingWants[pendingId];
      const onHand = stock[want.item] === undefined ? 0 : stock[want.item];
      if (onHand >= want.qty) {
        stock[want.item] = onHand - want.qty;
        reserved[pendingId] = { item: want.item, qty: want.qty };
        orders[pendingId] = "reserved";
        delete pendingWants[pendingId];
        queue.splice(i, 1);
      } else {
        i++;
      }
    }
  }

  function stockFor(item: string): number {
    return stock[item] === undefined ? 0 : stock[item];
  }

  function updateStock(item: string, fn: (current: number) => number): void {
    stock[item] = fn(stockFor(item));
  }

  function validateId(event: Record<string, unknown>, index: number): string {
    if (typeof event.id !== "string" || event.id.length === 0) {
      return "event " + index + ": bad id";
    }
    return "";
  }

  const handlers: Record<string, (event: Record<string, unknown>, index: number) => FulfillmentResult | void> = {
    order(event, index) {
      const err = validateId(event, index);
      if (err) return { ok: false, error: err };
      if (orders[event.id] !== undefined) {
        return { ok: false, error: "event " + index + ": duplicate order" };
      }
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      const qty = safeInt(event, "qty");
      if (qty === undefined || qty < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const available = stockFor(event.item);
      if (available >= qty) {
        stock[event.item] = available - qty;
        reserved[event.id] = { item: event.item, qty };
        orders[event.id] = "reserved";
      } else {
        queue.push(event.id);
        pendingWants[event.id] = { item: event.item, qty };
        orders[event.id] = "backordered";
      }
    },

    cancel(event, index) {
      const err = validateId(event, index);
      if (err) return { ok: false, error: err };
      const holding = reserved[event.id];
      if (holding !== undefined) {
        updateStock(holding.item, (v) => v + holding.qty);
        delete reserved[event.id];
        orders[event.id] = "cancelled";
        tryFillQueue();
      } else if (orders[event.id] === "backordered") {
        const idx = queue.indexOf(event.id);
        if (idx !== -1) {
          queue.splice(idx, 1);
          delete pendingWants[event.id];
        }
        orders[event.id] = "cancelled";
      } else {
        rejected++;
      }
    },

    ship(event, index) {
      const err = validateId(event, index);
      if (err) return { ok: false, error: err };
      const shipQty = safeInt(event, "qty");
      if (shipQty !== undefined && shipQty < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      const reservation = reserved[event.id];
      if (reservation === undefined) {
        rejected++;
      } else if (shipQty === undefined || shipQty === reservation.qty) {
        delete reserved[event.id];
        orders[event.id] = "shipped";
      } else if (shipQty < reservation.qty) {
        reservation.qty -= shipQty;
        orders[event.id] = "partial";
      } else {
        rejected++;
      }
    },

    restock(event, index) {
      if (typeof event.item !== "string" || event.item.length === 0) {
        return { ok: false, error: "event " + index + ": bad item" };
      }
      const qty = safeInt(event, "qty");
      if (qty === undefined || qty < 1) {
        return { ok: false, error: "event " + index + ": bad qty" };
      }
      updateStock(event.item, (v) => v + qty);
      tryFillQueue();
    },

    expire(event, index) {
      const err = validateId(event, index);
      if (err) return { ok: false, error: err };
      const holding = reserved[event.id];
      if (holding !== undefined) {
        updateStock(holding.item, (v) => v + holding.qty);
        delete reserved[event.id];
        orders[event.id] = "expired";
        tryFillQueue();
      } else {
        rejected++;
      }
    },
  };

  for (let index = 0; index < events!.length; index++) {
    const event = events![index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const eventType = event.type;
    if (typeof eventType !== "string" || handlers[eventType] === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const result = handlers[eventType](event, index);
    if (result) return result;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

function getStock(stock: Record<string, number>, item: string): number {
  return stock[item] ?? 0;
}

function trySatisfyQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = getStock(stock, want.item);
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position -= 1;
    }
  }
}

function processOrder(
  event: Record<string, unknown>,
  eid: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
): FulfillmentResult | undefined {
  if (eid.length === 0) return { ok: false, error: "bad id" };
  if (orders[eid] !== undefined) return { ok: false, error: "duplicate order" };
  if (typeof event.item !== "string" || event.item.length === 0) return { ok: false, error: "bad item" };
  if (!isPositiveInteger(event.qty)) return { ok: false, error: "bad qty" };
  const available = getStock(stock, event.item);
  if (available >= event.qty) {
    stock[event.item] = available - event.qty;
    reserved[eid] = { item: event.item, qty: event.qty };
    orders[eid] = "reserved";
  } else {
    queue.push(eid);
    pendingWants[eid] = { item: event.item, qty: event.qty };
    orders[eid] = "backordered";
  }
  return undefined;
}

function processCancel(
  event: Record<string, unknown>,
  eid: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  rejected: number,
): [number, FulfillmentResult | undefined] {
  if (eid.length === 0) return [rejected, { ok: false, error: "bad id" }];
  if (reserved[eid] !== undefined) {
    const holding = reserved[eid];
    stock[holding.item] = getStock(stock, holding.item) + holding.qty;
    delete reserved[eid];
    orders[eid] = "cancelled";
    trySatisfyQueue(stock, reserved, pendingWants, orders, queue);
  } else if (orders[eid] === "backordered") {
    const pos = queue.indexOf(eid);
    if (pos !== -1) queue.splice(pos, 1);
    delete pendingWants[eid];
    orders[eid] = "cancelled";
  } else {
    rejected += 1;
  }
  return [rejected, undefined];
}

function processShip(
  event: Record<string, unknown>,
  eid: string,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  rejected: number,
): [number, FulfillmentResult | undefined] {
  if (eid.length === 0) return [rejected, { ok: false, error: "bad id" }];
  if (event.qty !== undefined && !isPositiveInteger(event.qty)) return [rejected, { ok: false, error: "bad qty" }];
  if (reserved[eid] === undefined) {
    rejected += 1;
  } else if (event.qty === undefined || event.qty === reserved[eid].qty) {
    delete reserved[eid];
    orders[eid] = "shipped";
  } else if (event.qty < reserved[eid].qty) {
    reserved[eid].qty -= event.qty;
    orders[eid] = "partial";
  } else {
    rejected += 1;
  }
  return [rejected, undefined];
}

function processRestock(
  event: Record<string, unknown>,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
): FulfillmentResult | undefined {
  if (typeof event.item !== "string" || event.item.length === 0) return { ok: false, error: "bad item" };
  if (!isPositiveInteger(event.qty)) return { ok: false, error: "bad qty" };
  stock[event.item] = getStock(stock, event.item) + event.qty;
  trySatisfyQueue(stock, reserved, pendingWants, orders, queue);
  return undefined;
}

function processExpire(
  event: Record<string, unknown>,
  eid: string,
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
  queue: string[],
  rejected: number,
): [number, FulfillmentResult | undefined] {
  if (eid.length === 0) return [rejected, { ok: false, error: "bad id" }];
  if (reserved[eid] !== undefined) {
    const holding = reserved[eid];
    stock[holding.item] = getStock(stock, holding.item) + holding.qty;
    delete reserved[eid];
    orders[eid] = "expired";
    trySatisfyQueue(stock, reserved, pendingWants, orders, queue);
  } else {
    rejected += 1;
  }
  return [rejected, undefined];
}

const HANDLERS: Record<string, (event: Record<string, unknown>, eid: string, ctx: Context) => [number, FulfillmentResult | undefined]> = {
  order: (event, eid, ctx) => {
    const r = processOrder(event, eid, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders, ctx.queue);
    return [ctx.rejected, r];
  },
  cancel: (event, eid, ctx) => processCancel(event, eid, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders, ctx.queue, ctx.rejected),
  ship: (event, eid, ctx) => processShip(event, eid, ctx.reserved, ctx.orders, ctx.rejected),
  restock: (event, eid, ctx) => {
    const r = processRestock(event, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders, ctx.queue);
    return [ctx.rejected, r];
  },
  expire: (event, eid, ctx) => processExpire(event, eid, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders, ctx.queue, ctx.rejected),
};

interface Context {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  orders: Record<string, string>;
  queue: string[];
  rejected: number;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInteger(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item];
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const orders: Record<string, string> = {};
  const queue: string[] = [];
  let rejected = 0;

  const ctx: Context = { stock, reserved, pendingWants, orders, queue, rejected };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: `event ${index}: malformed` };
    }

    const eid = String(event.id ?? "");
    const handler = HANDLERS[String(event.type)];
    if (!handler) return { ok: false, error: `event ${index}: bad type` };

    const [newRejected, err] = handler(event, eid, ctx);
    if (err) {
      return { ok: false, error: `event ${index}: ${err.error}` };
    }
    rejected = newRejected;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] += 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = `orders=${Object.keys(orders).length}`;
  for (const status of STATUSES) {
    line += `;${status}=${counts[status]}`;
  }
  return `${line};rejected=${rejected}`;
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function getStock(stock: Record<string, number>, item: string): number {
  return stock[item] ?? 0;
}

function setStock(stock: Record<string, number>, item: string, fn: (current: number) => number): void {
  stock[item] = fn(getStock(stock, item));
}

function fulfillPendingFromQueue(
  queue: string[],
  pendingWants: Record<string, Want>,
  reserved: Record<string, Want>,
  orders: Record<string, string>,
  stock: Record<string, number>,
): void {
  for (let i = 0; i < queue.length; i++) {
    const pendingId = queue[i];
    const want = pendingWants[pendingId];
    if (getStock(stock, want.item) >= want.qty) {
      setStock(stock, want.item, (current) => current - want.qty);
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(i, 1);
      i--;
    }
  }
}

type EventContext = {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
};

type Handler = (event: Record<string, unknown>, index: number, ctx: EventContext) => FulfillmentResult | void;

const handlerMap: Record<string, Handler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

function handleOrder(event: Record<string, unknown>, index: number, ctx: EventContext): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  if (ctx.orders[id] !== undefined) {
    return { ok: false, error: "event " + index + ": duplicate order" };
  }
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  const qty = event.qty;
  if (!Number.isInteger(qty) || qty < 1) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  if (getStock(ctx.stock, item) >= qty) {
    setStock(ctx.stock, item, (current) => current - qty);
    ctx.reserved[id] = { item, qty };
    ctx.orders[id] = "reserved";
  } else {
    ctx.queue.push(id);
    ctx.pendingWants[id] = { item, qty };
    ctx.orders[id] = "backordered";
  }
}

function handleCancel(event: Record<string, unknown>, index: number, ctx: EventContext): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const reservation = ctx.reserved[id];
  if (reservation !== undefined) {
    setStock(ctx.stock, reservation.item, (current) => current + reservation.qty);
    delete ctx.reserved[id];
    ctx.orders[id] = "cancelled";
    fulfillPendingFromQueue(ctx.queue, ctx.pendingWants, ctx.reserved, ctx.orders, ctx.stock);
  } else if (ctx.orders[id] === "backordered") {
    ctx.queue.splice(ctx.queue.indexOf(id), 1);
    delete ctx.pendingWants[id];
    ctx.orders[id] = "cancelled";
  } else {
    ctx.rejected++;
  }
}

function handleShip(event: Record<string, unknown>, index: number, ctx: EventContext): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const shipQty = event.qty;
  if (shipQty !== undefined && (!Number.isInteger(shipQty) || shipQty < 1)) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const shipReservation = ctx.reserved[id];
  if (shipReservation === undefined) {
    ctx.rejected++;
  } else if (shipQty === undefined || shipQty === shipReservation.qty) {
    delete ctx.reserved[id];
    ctx.orders[id] = "shipped";
  } else if (shipQty < shipReservation.qty) {
    shipReservation.qty -= shipQty;
    ctx.orders[id] = "partial";
  } else {
    ctx.rejected++;
  }
}

function handleRestock(event: Record<string, unknown>, index: number, ctx: EventContext): FulfillmentResult | void {
  const item = event.item;
  if (typeof item !== "string" || item.length === 0) {
    return { ok: false, error: "event " + index + ": bad item" };
  }
  const restockQty = event.qty;
  if (!Number.isInteger(restockQty) || restockQty < 1) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  setStock(ctx.stock, item, (current) => current + restockQty);
  fulfillPendingFromQueue(ctx.queue, ctx.pendingWants, ctx.reserved, ctx.orders, ctx.stock);
}

function handleExpire(event: Record<string, unknown>, index: number, ctx: EventContext): FulfillmentResult | void {
  const id = event.id;
  if (typeof id !== "string" || id.length === 0) {
    return { ok: false, error: "event " + index + ": bad id" };
  }
  const expireReservation = ctx.reserved[id];
  if (expireReservation !== undefined) {
    setStock(ctx.stock, expireReservation.item, (current) => current + expireReservation.qty);
    delete ctx.reserved[id];
    ctx.orders[id] = "expired";
    fulfillPendingFromQueue(ctx.queue, ctx.pendingWants, ctx.reserved, ctx.orders, ctx.stock);
  } else {
    ctx.rejected++;
  }
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const value = rawStock[item];
    if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = value;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const ctx: EventContext = { stock, orders, reserved, pendingWants, queue, rejected: 0 };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const eventType = event.type;
    if (typeof eventType !== "string") {
      return { ok: false, error: "event " + index + ": bad type" };
    }

    const handler = handlerMap[eventType];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }

    const result = handler(event, index, ctx);
    if (result !== undefined && !result.ok) {
      return result;
    }
  }

  ctx.rejected = rejected;

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    const orderStatus = orders[id];
    counts[orderStatus] = (counts[orderStatus] ?? 0) + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface Want {
  item: string;
  qty: number;
}

interface OrderEvent {
  type: "order";
  id: string;
  item: string;
  qty: number;
}

interface CancelEvent {
  type: "cancel";
  id: string;
}

interface ShipEvent {
  type: "ship";
  id: string;
  qty?: number;
}

interface RestockEvent {
  type: "restock";
  item: string;
  qty: number;
}

interface ExpireEvent {
  type: "expire";
  id: string;
}

type Event = OrderEvent | CancelEvent | ShipEvent | RestockEvent | ExpireEvent;

function isNumber(val: unknown): val is number {
  return typeof val === "number" && Number.isFinite(val);
}

function isNumberRecord(val: unknown): val is Record<string, number> {
  if (typeof val !== "object" || val === null) return false;
  const obj = val as Record<string, unknown>;
  for (const v of Object.values(obj)) {
    if (!isNumber(v) || Math.floor(v) !== v || v < 0) return false;
  }
  return true;
}

function fail(index: number, msg: string): string {
  return "event " + index + ": " + msg;
}

function parseEvent(raw: unknown, index: number): Event | string {
  if (typeof raw !== "object" || raw === null) {
    return "event " + index + ": malformed";
  }
  const e = raw as Record<string, unknown>;
  const type = e.type;
  if (type === "order") return validateOrderEvent(e, index);
  if (type === "cancel") return validateIdEvent(e, index);
  if (type === "ship") return validateShipEvent(e, index);
  if (type === "restock") return validateRestockEvent(e, index);
  if (type === "expire") return validateIdEvent(e, index);
  return "event " + index + ": bad type";
}

function validateOrderEvent(e: Record<string, unknown>, index: number): Event | string {
  if (!isStringField(e, "id", 1)) return fail(index, "bad id");
  if (!isStringField(e, "item", 1)) return fail(index, "bad item");
  const qty = e.qty;
  if (!isNumber(qty) || Math.floor(qty) !== qty || qty < 1) return fail(index, "bad qty");
  return { type: "order", id: e.id as string, item: e.item as string, qty };
}

function validateShipEvent(e: Record<string, unknown>, index: number): Event | string {
  if (!isStringField(e, "id", 1)) return fail(index, "bad id");
  const qty = e.qty;
  if (qty !== undefined) {
    if (!isNumber(qty) || Math.floor(qty) !== qty || qty < 1) return fail(index, "bad qty");
  }
  return { type: "ship", id: e.id as string, qty: qty as number | undefined };
}

function validateRestockEvent(e: Record<string, unknown>, index: number): Event | string {
  if (!isStringField(e, "item", 1)) return fail(index, "bad item");
  const qty = e.qty;
  if (!isNumber(qty) || Math.floor(qty) !== qty || qty < 1) return fail(index, "bad qty");
  return { type: "restock", item: e.item as string, qty };
}

function validateIdEvent(e: Record<string, unknown>, index: number): Event | string {
  if (!isStringField(e, "id", 1)) return fail(index, "bad id");
  return { type: e.type, id: e.id as string };
}

function isStringField(e: Record<string, unknown>, key: string, minLen: number): boolean {
  const val = e[key];
  return typeof val === "string" && val.length >= minLen;
}

function reserveStock(stock: Record<string, number>, item: string, qty: number): boolean {
  const available = stock[item] ?? 0;
  if (available >= qty) {
    stock[item] = available - qty;
    return true;
  }
  return false;
}

function tryFillQueue(
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  queue: string[],
  orders: Record<string, string>,
): void {
  let i = 0;
  while (i < queue.length) {
    const id = queue[i];
    const want = pendingWants[id];
    if (reserveStock(stock, want.item, want.qty)) {
      reserved[id] = { item: want.item, qty: want.qty };
      orders[id] = "reserved";
      delete pendingWants[id];
      queue.splice(i, 1);
    } else {
      i++;
    }
  }
}

type EventHandler = (
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: OrderEvent | CancelEvent | ShipEvent | RestockEvent | ExpireEvent,
) => { rejected: number };

function handleOrder(
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: OrderEvent,
): { rejected: number } {
  if (reserveStock(stock, event.item, event.qty)) {
    reserved[event.id] = { item: event.item, qty: event.qty };
    orders[event.id] = "reserved";
  } else {
    queue.push(event.id);
    pendingWants[event.id] = { item: event.item, qty: event.qty };
    orders[event.id] = "backordered";
  }
  return { rejected: 0 };
}

function handleCancel(
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: CancelEvent,
): { rejected: number } {
  const res = reserved[event.id];
  if (res) {
    stock[res.item] = (stock[res.item] ?? 0) + res.qty;
    delete reserved[event.id];
    orders[event.id] = "cancelled";
    tryFillQueue(stock, reserved, pendingWants, queue, orders);
  } else if (orders[event.id] === "backordered") {
    const idx = queue.indexOf(event.id);
    if (idx !== -1) {
      queue.splice(idx, 1);
      delete pendingWants[event.id];
    }
    orders[event.id] = "cancelled";
  } else {
    return { rejected: 1 };
  }
  return { rejected: 0 };
}

function handleShip(
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: ShipEvent,
): { rejected: number } {
  const target = reserved[event.id];
  if (!target) return { rejected: 1 };
  if (event.qty === undefined || event.qty === target.qty) {
    delete reserved[event.id];
    orders[event.id] = "shipped";
  } else if (event.qty < target.qty) {
    target.qty -= event.qty;
    orders[event.id] = "partial";
  } else {
    return { rejected: 1 };
  }
  return { rejected: 0 };
}

function handleRestock(
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: RestockEvent,
): { rejected: number } {
  stock[event.item] = (stock[event.item] ?? 0) + event.qty;
  tryFillQueue(stock, reserved, pendingWants, queue, orders);
  return { rejected: 0 };
}

function handleExpire(
  stock: Record<string, number>,
  orders: Record<string, string>,
  reserved: Record<string, Want>,
  queue: string[],
  pendingWants: Record<string, Want>,
  event: ExpireEvent,
): { rejected: number } {
  const res = reserved[event.id];
  if (res) {
    stock[res.item] = (stock[res.item] ?? 0) + res.qty;
    delete reserved[event.id];
    orders[event.id] = "expired";
    tryFillQueue(stock, reserved, pendingWants, queue, orders);
  } else {
    return { rejected: 1 };
  }
  return { rejected: 0 };
}

const EVENT_HANDLERS: Record<string, EventHandler> = {
  order: handleOrder,
  cancel: handleCancel,
  ship: handleShip,
  restock: handleRestock,
  expire: handleExpire,
};

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }

  const input = raw as Record<string, unknown>;

  if (!isNumberRecord(input.stock)) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = input.stock as Record<string, number>;

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  for (let i = 0; i < input.events.length; i++) {
    const parsed = parseEvent(input.events[i], i);
    if (typeof parsed === "string") {
      return { ok: false, error: parsed };
    }

    const eventType = parsed.type;
    if (eventType === "order" && orders[(parsed as OrderEvent).id]) {
      return { ok: false, error: "event " + i + ": duplicate order" };
    }
    const handler = EVENT_HANDLERS[eventType];
    rejected += handler(stock, orders, reserved, queue, pendingWants, parsed).rejected;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

interface EventInput {
  type?: unknown;
  id?: unknown;
  item?: unknown;
  qty?: unknown;
}

type OrderStatus = "reserved" | "backordered" | "shipped" | "partial" | "cancelled" | "expired";

type DispatchFn = (event: ValidEvent, ctx: Context) => void;

interface Context {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  orders: Record<string, string>;
  rejected: number;
}

const STATUSES: OrderStatus[] = [
  "reserved",
  "backordered",
  "shipped",
  "partial",
  "cancelled",
  "expired",
];

function tryFulfillQueue(ctx: Context): void {
  let position = 0;
  while (position < ctx.queue.length) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] === undefined ? 0 : ctx.stock[want.item];
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
    } else {
      position += 1;
    }
  }
}

function toNonEmptyString(value: unknown): string | false {
  if (typeof value === "string" && value.length > 0) {
    return value;
  }
  return false;
}

function toPositiveInt(value: unknown): number | false {
  if (typeof value === "number" && Number.isInteger(value)) {
    return value;
  }
  return false;
}

function validateStock(raw: Record<string, unknown>): Record<string, number> | FulfillmentResult {
  if (typeof raw.stock !== "object" || raw.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = raw.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    const qty = toPositiveInt(rawStock[item]);
    if (qty === false) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = qty;
  }
  return stock;
}

interface ValidEvent {
  type: "order" | "cancel" | "ship" | "restock" | "expire";
  data: ParsedOrder | ParsedCancel | ParsedShip | ParsedRestock | ParsedExpire;
}

interface ParsedOrder {
  id: string;
  item: string;
  qty: number;
}

interface ParsedCancel {
  id: string;
}

interface ParsedShip {
  id: string;
  qty: number | undefined;
}

interface ParsedRestock {
  item: string;
  qty: number;
}

interface ParsedExpire {
  id: string;
}

type ParseEventFn = (event: EventInput, index: number) => ValidEvent | FulfillmentResult;

function parseOrder(event: EventInput, index: number): ValidEvent | FulfillmentResult {
  const id = toNonEmptyString(event.id);
  if (id === false) return { ok: false, error: "event " + index + ": bad id" };
  const item = toNonEmptyString(event.item);
  if (item === false) return { ok: false, error: "event " + index + ": bad item" };
  const qty = toPositiveInt(event.qty);
  if (qty === false) return { ok: false, error: "event " + index + ": bad qty" };
  return { type: "order", data: { id, item, qty } };
}

function parseCancel(event: EventInput, index: number): ValidEvent | FulfillmentResult {
  const id = toNonEmptyString(event.id);
  if (id === false) return { ok: false, error: "event " + index + ": bad id" };
  return { type: "cancel", data: { id } };
}

function parseShip(event: EventInput, index: number): ValidEvent | FulfillmentResult {
  const id = toNonEmptyString(event.id);
  if (id === false) return { ok: false, error: "event " + index + ": bad id" };
  const rawQty = toPositiveInt(event.qty);
  if (rawQty === false && event.qty !== undefined) {
    return { ok: false, error: "event " + index + ": bad qty" };
  }
  const qty = rawQty === false ? undefined : rawQty;
  return { type: "ship", data: { id, qty } };
}

function parseRestock(event: EventInput, index: number): ValidEvent | FulfillmentResult {
  const item = toNonEmptyString(event.item);
  if (item === false) return { ok: false, error: "event " + index + ": bad item" };
  const qty = toPositiveInt(event.qty);
  if (qty === false) return { ok: false, error: "event " + index + ": bad qty" };
  return { type: "restock", data: { item, qty } };
}

function parseExpire(event: EventInput, index: number): ValidEvent | FulfillmentResult {
  const id = toNonEmptyString(event.id);
  if (id === false) return { ok: false, error: "event " + index + ": bad id" };
  return { type: "expire", data: { id } };
}

const PARSERS: Record<string, ParseEventFn> = {
  order: parseOrder,
  cancel: parseCancel,
  ship: parseShip,
  restock: parseRestock,
  expire: parseExpire,
};

function orderHandler(event: ValidEvent, ctx: Context): void {
  const data = event.data as { id: string; item: string; qty: number };
  const available = ctx.stock[data.item] === undefined ? 0 : ctx.stock[data.item];
  if (available >= data.qty) {
    ctx.stock[data.item] = available - data.qty;
    ctx.reserved[data.id] = { item: data.item, qty: data.qty };
    ctx.orders[data.id] = "reserved";
  } else {
    ctx.queue.push(data.id);
    ctx.pendingWants[data.id] = { item: data.item, qty: data.qty };
    ctx.orders[data.id] = "backordered";
  }
}

function cancelHandler(event: ValidEvent, ctx: Context): void {
  const data = event.data as { id: string };
  if (ctx.reserved[data.id] !== undefined) {
    const holding = ctx.reserved[data.id];
    const back = ctx.stock[holding.item] === undefined ? 0 : ctx.stock[holding.item];
    ctx.stock[holding.item] = back + holding.qty;
    delete ctx.reserved[data.id];
    ctx.orders[data.id] = "cancelled";
    tryFulfillQueue(ctx);
  } else if (ctx.orders[data.id] === "backordered") {
    const pos = ctx.queue.indexOf(data.id);
    if (pos !== -1) {
      ctx.queue.splice(pos, 1);
      delete ctx.pendingWants[data.id];
    }
    ctx.orders[data.id] = "cancelled";
  } else {
    ctx.rejected += 1;
  }
}

function shipHandler(event: ValidEvent, ctx: Context): void {
  const data = event.data as { id: string; qty: number | undefined };
  if (ctx.reserved[data.id] === undefined) {
    ctx.rejected += 1;
  } else {
    const want = ctx.reserved[data.id];
    if (data.qty === undefined || data.qty === want.qty) {
      delete ctx.reserved[data.id];
      ctx.orders[data.id] = "shipped";
    } else if (data.qty < want.qty) {
      want.qty -= data.qty;
      ctx.orders[data.id] = "partial";
    } else {
      ctx.rejected += 1;
    }
  }
}

function restockHandler(event: ValidEvent, ctx: Context): void {
  const data = event.data as { item: string; qty: number };
  const held = ctx.stock[data.item] === undefined ? 0 : ctx.stock[data.item];
  ctx.stock[data.item] = held + data.qty;
  tryFulfillQueue(ctx);
}

function expireHandler(event: ValidEvent, ctx: Context): void {
  const data = event.data as { id: string };
  if (ctx.reserved[data.id] !== undefined) {
    const holding = ctx.reserved[data.id];
    const back = ctx.stock[holding.item] === undefined ? 0 : ctx.stock[holding.item];
    ctx.stock[holding.item] = back + holding.qty;
    delete ctx.reserved[data.id];
    ctx.orders[data.id] = "expired";
    tryFulfillQueue(ctx);
  } else {
    ctx.rejected += 1;
  }
}

const HANDLERS: Record<string, DispatchFn> = {
  order: orderHandler,
  cancel: cancelHandler,
  ship: shipHandler,
  restock: restockHandler,
  expire: expireHandler,
};

function processEvent(
  event: EventInput,
  index: number,
  ctx: Context,
): FulfillmentResult | void {
  const parsed = PARSERS[event.type]?.(event, index);
  if (!parsed) {
    return { ok: false, error: "event " + index + ": bad type" };
  }
  if ("error" in parsed) {
    return parsed;
  }
  const dispatchFn = HANDLERS[parsed.type];
  if (dispatchFn === undefined) {
    return { ok: false, error: "event " + index + ": bad type" };
  }
  dispatchFn(parsed, ctx);
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const _id of Object.keys(orders)) {
    counts[orders[_id]] = counts[orders[_id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

interface ParsedInput {
  stock: Record<string, number>;
  events: unknown[];
}

function parseInput(raw: unknown): ParsedInput | FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  const stock = validateStock(input);
  if ("error" in stock) {
    return stock;
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  return { stock, events: input.events };
}

function processEventsInternal(
  stock: Record<string, number>,
  events: unknown[],
): FulfillmentResult {
  const ctx: Context = {
    stock,
    reserved: {},
    pendingWants: {},
    queue: [],
    orders: {},
    rejected: 0,
  };

  for (let index = 0; index < events.length; index++) {
    const rawEvent = events[index];
    if (typeof rawEvent !== "object" || rawEvent === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const event = rawEvent as EventInput;

    const result = processEvent(event, index, ctx);
    if (result && !result.ok) {
      return result;
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

export function processEvents(raw: unknown): FulfillmentResult {
  const parsed = parseInput(raw);
  if ("error" in parsed) {
    return parsed;
  }
  return processEventsInternal(parsed.stock, parsed.events);
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const orders: Record<string, string> = {};
  const reserved: Record<string, Want> = {};
  const pendingWants: Record<string, Want> = {};
  const queue: string[] = [];
  let rejected = 0;

  const dispatch: Record<string, (event: Record<string, unknown>, ctx: Context) => Result> = {
    order: handleOrder,
    cancel: handleCancel,
    ship: handleShip,
    restock: handleRestock,
    expire: handleExpire,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: `event ${index}: malformed` };
    }
    const handler = dispatch[String(event.type)];
    if (!handler) return { ok: false, error: `event ${index}: bad type` };
    const result = handler(event, { index, stock, orders, reserved, pendingWants, queue, rejected });
    if (!result.ok) return result;
    rejected = (result as { ok: true; state: Partial<Context> }).state.rejected ?? rejected;
  }

  return {
    ok: true,
    orders,
    stock,
    queue,
    rejected,
    report: buildReport(orders, rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"] as const;

interface Context {
  index: number;
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

interface Result { ok: true; state: Partial<Context> } | { ok: false; error: string };

function handleOrder(event: Record<string, unknown>, ctx: Context): Result {
  const idx = ctx.index;
  if (typeof event.id !== "string" || event.id.length === 0) return errorAt(idx, "bad id");
  if (ctx.orders[event.id] !== undefined) return errorAt(idx, "duplicate order");
  if (typeof event.item !== "string" || event.item.length === 0) return errorAt(idx, "bad item");
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return errorAt(idx, "bad qty");

  const qty = event.qty as number;
  const available = ctx.stock[event.item] ?? 0;
  if (available >= qty) {
    ctx.stock[event.item] = available - qty;
    ctx.reserved[event.id] = { item: event.item, qty };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item: event.item, qty };
    ctx.orders[event.id] = "backordered";
  }
  return { ok: true, state: {} };
}

function handleCancel(event: Record<string, unknown>, ctx: Context): Result {
  const idx = ctx.index;
  if (typeof event.id !== "string" || event.id.length === 0) return errorAt(idx, "bad id");

  const rid = event.id as string;
  if (ctx.reserved[rid] !== undefined) {
    const holding = ctx.reserved[rid];
    ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
    delete ctx.reserved[rid];
    ctx.orders[rid] = "cancelled";
    fanOut(ctx.queue, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders);
  } else if (ctx.orders[rid] === "backordered") {
    const qidx = ctx.queue.indexOf(rid);
    if (qidx !== -1) ctx.queue.splice(qidx, 1);
    delete ctx.pendingWants[rid];
    ctx.orders[rid] = "cancelled";
  } else {
    ctx.rejected++;
  }
  return { ok: true, state: { rejected: ctx.rejected } };
}

function handleShip(event: Record<string, unknown>, ctx: Context): Result {
  const idx = ctx.index;
  if (typeof event.id !== "string" || event.id.length === 0) return errorAt(idx, "bad id");
  if (event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)) {
    return { ok: false, error: `event ${idx}: bad qty` };
  }

  const rid = event.id as string;
  const shipQty = event.qty as number | undefined;
  if (ctx.reserved[rid] === undefined) {
    ctx.rejected++;
  } else if (shipQty === undefined || shipQty === ctx.reserved[rid].qty) {
    delete ctx.reserved[rid];
    ctx.orders[rid] = "shipped";
  } else if (shipQty! < ctx.reserved[rid].qty) {
    ctx.reserved[rid].qty -= shipQty!;
    ctx.orders[rid] = "partial";
  } else {
    ctx.rejected++;
  }
  return { ok: true, state: { rejected: ctx.rejected } };
}

function handleRestock(event: Record<string, unknown>, ctx: Context): Result {
  const idx = ctx.index;
  if (typeof event.item !== "string" || event.item.length === 0) return errorAt(idx, "bad item");
  if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return errorAt(idx, "bad qty");

  const qty = event.qty as number;
  ctx.stock[event.item] = (ctx.stock[event.item] ?? 0) + qty;
  fanOut(ctx.queue, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders);
  return { ok: true, state: {} };
}

function handleExpire(event: Record<string, unknown>, ctx: Context): Result {
  const idx = ctx.index;
  if (typeof event.id !== "string" || event.id.length === 0) return errorAt(idx, "bad id");

  const rid = event.id as string;
  if (ctx.reserved[rid] !== undefined) {
    const holding = ctx.reserved[rid];
    ctx.stock[holding.item] = (ctx.stock[holding.item] ?? 0) + holding.qty;
    delete ctx.reserved[rid];
    ctx.orders[rid] = "expired";
    fanOut(ctx.queue, ctx.stock, ctx.reserved, ctx.pendingWants, ctx.orders);
  } else {
    ctx.rejected++;
  }
  return { ok: true, state: { rejected: ctx.rejected } };
}

function fanOut(
  queue: string[],
  stock: Record<string, number>,
  reserved: Record<string, Want>,
  pendingWants: Record<string, Want>,
  orders: Record<string, string>,
): void {
  for (let position = 0; position < queue.length; position++) {
    const pendingId = queue[position];
    const want = pendingWants[pendingId];
    const onHand = stock[want.item] ?? 0;
    if (onHand >= want.qty) {
      stock[want.item] = onHand - want.qty;
      reserved[pendingId] = { item: want.item, qty: want.qty };
      orders[pendingId] = "reserved";
      delete pendingWants[pendingId];
      queue.splice(position, 1);
      position--;
    }
  }
}

function errorAt(index: number, message: string): { ok: false; error: string } {
  return { ok: false, error: `event ${index}: ${message}` };
}

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  const parts: string[] = ["orders=" + Object.keys(orders).length];
  for (const status of STATUSES) {
    parts.push(status + "=" + counts[status]);
  }
  parts.push("rejected=" + rejected);
  return parts.join(";");
}

interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

interface Context {
  stock: Record<string, number>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  orders: Record<string, string>;
  queue: string[];
  rejected: number;
}

function tryFulfillQueue(ctx: Context): void {
  for (let position = 0; position < ctx.queue.length; position++) {
    const pendingId = ctx.queue[position];
    const want = ctx.pendingWants[pendingId];
    const onHand = ctx.stock[want.item] === undefined ? 0 : ctx.stock[want.item];
    if (onHand >= want.qty) {
      ctx.stock[want.item] = onHand - want.qty;
      ctx.reserved[pendingId] = { item: want.item, qty: want.qty };
      ctx.orders[pendingId] = "reserved";
      delete ctx.pendingWants[pendingId];
      ctx.queue.splice(position, 1);
      position--;
    }
  }
}

function processOrder(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) return "event " + index + ": bad id";
  if (ctx.orders[event.id] !== undefined) return "event " + index + ": duplicate order";
  if (typeof event.item !== "string" || event.item.length === 0) return "event " + index + ": bad item";
  if (!isPositiveInteger(event.qty)) return "event " + index + ": bad qty";

  const qty = event.qty as number;
  const available = ctx.stock[event.item] === undefined ? 0 : ctx.stock[event.item];
  if (available >= qty) {
    ctx.stock[event.item] = available - qty;
    ctx.reserved[event.id] = { item: event.item, qty };
    ctx.orders[event.id] = "reserved";
  } else {
    ctx.queue.push(event.id);
    ctx.pendingWants[event.id] = { item: event.item, qty };
    ctx.orders[event.id] = "backordered";
  }
  return null;
}

function processCancel(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) return "event " + index + ": bad id";

  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    ctx.stock[holding.item] =
      (ctx.stock[holding.item] === undefined ? 0 : ctx.stock[holding.item]) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "cancelled";
    tryFulfillQueue(ctx);
  } else if (ctx.orders[event.id] === "backordered") {
    const pos = ctx.queue.indexOf(event.id);
    if (pos !== -1) ctx.queue.splice(pos, 1);
    delete ctx.pendingWants[event.id];
    ctx.orders[event.id] = "cancelled";
  } else {
    ctx.rejected++;
  }
  return null;
}

function processShip(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) return "event " + index + ": bad id";
  if (event.qty !== undefined && !isPositiveInteger(event.qty)) return "event " + index + ": bad qty";

  if (ctx.reserved[event.id] === undefined) {
    ctx.rejected++;
  } else if (event.qty === undefined || event.qty === ctx.reserved[event.id].qty) {
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "shipped";
  } else if ((event.qty as number) < ctx.reserved[event.id].qty) {
    ctx.reserved[event.id].qty -= event.qty as number;
    ctx.orders[event.id] = "partial";
  } else {
    ctx.rejected++;
  }
  return null;
}

function processRestock(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.item !== "string" || event.item.length === 0) return "event " + index + ": bad item";
  if (!isPositiveInteger(event.qty)) return "event " + index + ": bad qty";

  const qty = event.qty as number;
  ctx.stock[event.item] =
    (ctx.stock[event.item] === undefined ? 0 : ctx.stock[event.item]) + qty;
  tryFulfillQueue(ctx);
  return null;
}

function processExpire(ctx: Context, event: Record<string, unknown>, index: number): string | null {
  if (typeof event.id !== "string" || event.id.length === 0) return "event " + index + ": bad id";

  if (ctx.reserved[event.id] !== undefined) {
    const holding = ctx.reserved[event.id];
    ctx.stock[holding.item] =
      (ctx.stock[holding.item] === undefined ? 0 : ctx.stock[holding.item]) + holding.qty;
    delete ctx.reserved[event.id];
    ctx.orders[event.id] = "expired";
    tryFulfillQueue(ctx);
  } else {
    ctx.rejected++;
  }
  return null;
}

const eventHandlers: Record<string, (ctx: Context, event: Record<string, unknown>, index: number) => string | null> = {
  order: processOrder,
  cancel: processCancel,
  ship: processShip,
  restock: processRestock,
  expire: processExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;

  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!isNonNegativeInteger(rawStock[item])) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item];
  }

  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const ctx: Context = {
    stock,
    reserved: {},
    pendingWants: {},
    orders: {},
    queue: [],
    rejected: 0,
  };

  const events = input.events as Record<string, unknown>[];

  for (let index = 0; index < events.length; index++) {
    const event = events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }

    const handler = eventHandlers[event.type];
    if (handler === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }

    const error = handler(ctx, event, index);
    if (error !== null) {
      return { ok: false, error };
    }
  }

  return {
    ok: true,
    orders: ctx.orders,
    stock: ctx.stock,
    queue: ctx.queue,
    rejected: ctx.rejected,
    report: buildReport(ctx.orders, ctx.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] += 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line += ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

