export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

function isNonEmptyString(value: string): boolean {
  return value.trim().length > 0;
}

function checkRequired(value: string, message: string): string | null {
  return isNonEmptyString(value) ? null : message;
}

function validateAddress(address: Address | null, label: string): string[] {
  if (address === null) {
    return [`${label} address is required`];
  }
  const errors: string[] = [];
  if (!isNonEmptyString(address.postalCode)) {
    errors.push(`${label} postal code is required`);
  }
  return errors;
}

const VALID_CURRENCIES = new Set(["USD", "EUR"]);

const REQUIRED_STRING_RULES: Array<{ test: string; message: string }> = [
  { test: order.id, message: "order id is required" },
  { test: order.customerId, message: "customer id is required" },
];

function runRequiredChecks(order: Order): string[] {
  const rules: Array<{ test: string; message: string }> = [
    { test: order.id, message: "order id is required" },
    { test: order.customerId, message: "customer id is required" },
  ];
  return rules
    .map(({ test, message }) => checkRequired(test, message))
    .filter((e): e is string => e !== null);
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  errors.push(...runRequiredChecks(order));

  if (order.items.length === 0) {
    errors.push("order must contain at least one item");
  } else {
    for (const item of order.items) {
      if (item.quantity <= 0) {
        errors.push(`item ${item.sku} has a non-positive quantity`);
      }
    }
  }

  errors.push(...validateAddress(order.shippingAddress, "shipping"));
  errors.push(...validateAddress(order.billingAddress, "billing"));

  if (order.totalCents <= 0) {
    errors.push("order total must be positive");
  }

  if (!VALID_CURRENCIES.has(order.currency)) {
    errors.push(`unsupported currency: ${order.currency}`);
  }

  return { valid: errors.length === 0, errors };
}

export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const VALID_CURRENCIES = new Set(["USD", "EUR"]);

function validateId(order: Order): string[] {
  if (order.id.length === 0) return ["order id is required"];
  return [];
}

function validateCustomerId(order: Order): string[] {
  if (order.customerId.length === 0) return ["customer id is required"];
  return [];
}

function validateItems(order: Order): string[] {
  if (order.items.length === 0) return ["order must contain at least one item"];
  const errors: string[] = [];
  for (const item of order.items) {
    if (item.quantity <= 0) {
      errors.push(`item ${item.sku} has a non-positive quantity`);
