type OrderValidator = (order: Order) => string[];

const validators: OrderValidator[] = [
  (order) => order.id.length === 0 ? ["order id is required"] : [],
  (order) => order.customerId.length === 0 ? ["customer id is required"] : [],
  (order) => {
    if (order.items.length === 0) return ["order must contain at least one item"];
    return order.items
      .filter((item) => item.quantity <= 0)
      .map((item) => `item ${item.sku} has a non-positive quantity`);
  },
  (order) => {
    if (order.shippingAddress === null) return ["shipping address is required"];
    const code = order.shippingAddress.postalCode;
    if (code.length === 0 || code.trim().length === 0) return ["shipping postal code is required"];
    return [];
  },
  (order) => order.billingAddress === null ? ["billing address is required"] : [],
  (order) => order.totalCents <= 0 ? ["order total must be positive"] : [],
  (order) =>
    !SUPPORTED_CURRENCIES.has(order.currency)
      ? [`unsupported currency: ${order.currency}`]
      : [],
];

export function validateOrder(order: Order): ValidationResult {
  const errors = validators.flatMap((validator) => validator(order));

  return { valid: errors.length === 0, errors };
}

