  if (order.customerId.length === 0) {
    errors.push("customer id is required");
  }
  return errors;
}

function validateItems(items: OrderItem[]): string[] {
  const errors: string[] = [];
  if (items.length === 0) {
    errors.push("order must contain at least one item");
  } else {
    for (const item of items) {
      if (item.quantity <= 0) {
        errors.push(`item ${item.sku} has a non-positive quantity`);
      }
    }
  }
  return errors;
}

function validateShippingAddress(address: Address | null): string[] {
  const errors: string[] = [];
  if (address === null) {
    errors.push("shipping address is required");
  } else if (address.postalCode.trim().length === 0) {
    errors.push("shipping postal code is required");
  }
  return errors;
}

function validateBillingAddress(address: Address | null): string[] {
  if (address === null) {
    return ["billing address is required"];
  }
  return [];
}

function validateTotals(order: Order): string[] {
  const errors: string[] = [];
  if (order.totalCents <= 0) {
    errors.push("order total must be positive");
  }
  if (order.currency !== "USD" && order.currency !== "EUR") {
    errors.push(`unsupported currency: ${order.currency}`);
  }
  return errors;
}

export function validateOrder(order: Order): ValidationResult {
  const errors = [
    ...validateRequiredFields(order),
    ...validateItems(order.items),
    ...validateShippingAddress(order.shippingAddress),
    ...validateBillingAddress(order.billingAddress),
    ...validateTotals(order),
  ];
  return { valid: errors.length === 0, errors };
}

