export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = ["exponential", "linear"] as const;

function parseNumber(
  key: string,
  min: number,
  max: number | undefined,
  raw: Record<string, string>,
): number | undefined {
  const value = Number(raw[key]);
  if (Number.isInteger(value) && value >= min && (max === undefined || value <= max)) {
    return value;
  }
  return undefined;
}

function parseBoolean(key: string, raw: Record<string, string>): boolean | undefined {
  const value = raw[key];
  if (value === "true") return true;
  if (value === "false") return false;
  return undefined;
}

function parseStringEnum(
  key: string,
  valid: readonly string[],
  raw: Record<string, string>,
): string | undefined {
  const value = raw[key];
  if (value !== undefined && valid.includes(value)) {
    return value;
  }
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  return {
    maxAttempts: parseNumber("maxAttempts", 1, 10, raw) ?? DEFAULT_RETRY_CONFIG.maxAttempts,
    backoffMs: parseNumber("backoffMs", 0, undefined, raw) ?? DEFAULT_RETRY_CONFIG.backoffMs,
    jitter: parseBoolean("jitter", raw) ?? DEFAULT_RETRY_CONFIG.jitter,
    mode: parseStringEnum("mode", VALID_MODES, raw) ?? DEFAULT_RETRY_CONFIG.mode,
  };
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const MAX_ATTEMPTS = 10;
const MIN_ATTEMPTS = 1;
const VALID_MODES = ["exponential", "linear"] as const;

type FieldParser = (raw: string) => number | boolean | string | null;

const FIELD_PARSERS: Record<keyof RetryConfig, FieldParser> = {
  maxAttempts: (raw) => {
    const value = Number(raw);
    return Number.isInteger(value) && value >= MIN_ATTEMPTS && value <= MAX_ATTEMPTS
      ? value
      : null;
  },
  backoffMs: (raw) => {
    const value = Number(raw);
    return Number.isInteger(value) && value >= 0 ? value : null;
  },
  jitter: (raw) => {
    const lower = raw.toLowerCase();
    if (lower === "true") return true;
    if (lower === "false") return false;
    return null;
  },
  mode: (raw) => {
    return VALID_MODES.includes(raw as (typeof VALID_MODES)[number]) ? raw : null;
  },
};

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const [key, parse] of Object.entries(FIELD_PARSERS)) {
    const value = raw[key];
    if (value === undefined) continue;

    const parsed = parse(value);
    if (parsed !== null) {
      config[key as keyof RetryConfig] = parsed;
    }
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

function parseIntegerWithBounds(raw: string, min: number, max: number): number | null {
  const trimmed = raw.trim();
  const value = Number(trimmed);
  if (Number.isInteger(value) && value >= min && value <= max) {
    return value;
  }
  return null;
}

function parseBoolean(raw: string): boolean | null {
  const trimmed = raw.trim().toLowerCase();
  if (trimmed === "true") return true;
  if (trimmed === "false") return false;
  return null;
}

function parseMode(raw: string): string | null {
  const trimmed = raw.trim();
  return VALID_MODES.has(trimmed) ? trimmed : null;
}

const FIELD_PARSERS: Record<
  keyof RetryConfig,
  (raw: string) => RetryConfig[keyof RetryConfig] | null
> = {
  maxAttempts: (raw) => parseIntegerWithBounds(raw, 1, 10),
  backoffMs: (raw) => {
    const value = parseIntegerWithBounds(raw, 0, Infinity);
    return value;
  },
  jitter: (raw) => parseBoolean(raw),
  mode: (raw) => parseMode(raw),
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const key of Object.keys(FIELD_PARSERS) as Array<keyof RetryConfig>) {
    const rawValue = raw[key];
    if (rawValue !== undefined) {
      const parsed = FIELD_PARSERS[key](rawValue);
      if (parsed !== null) {
        config[key] = parsed;
      }
    }
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: "exponential" | "linear";
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

type ParsedValue<T> = { valid: true; value: T } | { valid: false };

function tryParseNumber(raw: string, min: number, max: number): ParsedValue<number> {
  const value = Number(raw);
  if (Number.isInteger(value) && value >= min && value <= max) {
    return { valid: true, value };
  }
  return { valid: false };
}

function tryParseBoolean(raw: string): ParsedValue<boolean> {
  if (raw === "true") return { valid: true, value: true };
  if (raw === "false") return { valid: true, value: false };
  return { valid: false };
}

const VALID_MODES = new Set(["exponential", "linear"]) as Set<RetryConfig["mode"]>;

function tryParseMode(raw: string): ParsedValue<RetryConfig["mode"]> {
  if (VALID_MODES.has(raw)) {
    return { valid: true, value: raw };
  }
  return { valid: false };
}

type ParseFn<T> = (raw: string) => ParsedValue<T>;

const FIELD_PARSERS: Record<string, ParseFn<any>> = {
  maxAttempts: (raw) => tryParseNumber(raw, 1, 10),
  backoffMs: (raw) => tryParseNumber(raw, 0, Infinity),
  jitter: tryParseBoolean,
  mode: tryParseMode,
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const keys = Object.keys(raw);
  for (const key of keys) {
    const parseFn = FIELD_PARSERS[key];
    if (parseFn && Object.prototype.hasOwnProperty.call(raw, key)) {
      const result = parseFn(raw[key]);
      if (result.valid) {
        config[key as keyof RetryConfig] = result.value;
      }
    }
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: Required<RetryConfig> = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

export function parseRetryConfig(
  raw: Record<string, string>
): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseIntegerInRange(raw.maxAttempts, 1, 10);
  if (maxAttempts !== null) {
    config.maxAttempts = maxAttempts;
  }

  const backoffMs = parseNonNegativeInteger(raw.backoffMs);
  if (backoffMs !== null) {
    config.backoffMs = backoffMs;
  }

  const jitter = parseBooleanString(raw.jitter);
  if (jitter !== null) {
    config.jitter = jitter;
  }

  const mode = parseEnumString(raw.mode, VALID_MODES);
  if (mode !== null) {
    config.mode = mode;
  }

  return config;
}

function parseIntegerInRange(
  raw: string | undefined,
  min: number,
  max: number
): number | null {
  if (raw === undefined) return null;
  const value = Number(raw);
  return Number.isInteger(value) && value >= min && value <= max ? value : null;
}

function parseNonNegativeInteger(raw: string | undefined): number | null {
  if (raw === undefined) return null;
  const value = Number(raw);
  return Number.isInteger(value) && value >= 0 ? value : null;
}

function parseBooleanString(raw: string | undefined): boolean | null {
  if (raw === undefined) return null;
  switch (raw) {
    case "true":
      return true;
    case "false":
      return false;
    default:
      return null;
  }
}

function parseEnumString<T extends string>(
  raw: string | undefined,
  validValues: Set<T>
): T | null {
  if (raw === undefined) return null;
  return validValues.has(raw) ? raw : null;
}

export interface RetryConfig {
