};

function parseBool(value: string | undefined): boolean | undefined {
  return value === undefined ? undefined : JITTER_MAP[value.trim().toLowerCase()];
}

const MODE_MAP: Record<string, "exponential" | "linear"> = {
  exponential: "exponential",
  linear: "linear",
};

function parseMode(value: string | undefined): "exponential" | "linear" | undefined {
  return value === undefined ? undefined : MODE_MAP[value.trim().toLowerCase()];
}

export function parseRetryConfig(raw?: Record<string, string> | null): RetryConfig {
  if (!raw) return { ...DEFAULT_RETRY_CONFIG };

  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = parseInteger(raw.maxAttempts, 1, 10);
  if (maxAttempts !== undefined) config.maxAttempts = maxAttempts;

  const backoffMs = parseInteger(raw.backoffMs, 0, Infinity);
  if (backoffMs !== undefined) config.backoffMs = backoffMs;

  const jitter = parseBool(raw.jitter);
  if (jitter !== undefined) config.jitter = jitter;

  const mode = parseMode(raw.mode);
  if (mode !== undefined) config.mode = mode;

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: "exponential" | "linear";
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES: ReadonlySet<string> = new Set(["exponential", "linear"]);

function tryParseMaxAttempts(raw: string | undefined): number | undefined {
  const value = Number(raw);
  if (Number.isInteger(value) && value >= 1 && value <= 10) {
    return value;
  }
  return undefined;
}

function tryParseBackoffMs(raw: string | undefined): number | undefined {
  const value = Number(raw);
  if (Number.isInteger(value) && value >= 0) {
    return value;
  }
  return undefined;
}

function tryParseJitter(raw: string | undefined): boolean | undefined {
  if (raw === undefined) return undefined;
  const lower = raw.toLowerCase();
  if (lower === "true") return true;
  if (lower === "false") return false;
  return undefined;
}

function tryParseMode(raw: string | undefined): "exponential" | "linear" | undefined {
  if (VALID_MODES.has(raw)) {
    return raw as "exponential" | "linear";
  }
  return undefined;
}

export function parseRetryConfig(raw: Record<string, string | undefined>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const maxAttempts = tryParseMaxAttempts(raw.maxAttempts);
  if (maxAttempts !== undefined) config.maxAttempts = maxAttempts;

  const backoffMs = tryParseBackoffMs(raw.backoffMs);
  if (backoffMs !== undefined) config.backoffMs = backoffMs;

  const jitter = tryParseJitter(raw.jitter);
  if (jitter !== undefined) config.jitter = jitter;

  const mode = tryParseMode(raw.mode);
  if (mode !== undefined) config.mode = mode;

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: "exponential" | "linear";
}

const DEFAULT_MAX_ATTEMPTS = 3;
const DEFAULT_BACKOFF_MS = 200;
const VALID_MODES: Record<string, "exponential" | "linear"> = {
  exponential: "exponential",
  linear: "linear",
};

function parseMaxAttempts(raw: Record<string, string>): number {
  const value = Number(raw.maxAttempts);
  if (Number.isInteger(value) && value >= 1 && value <= 10) {
    return value;
  }
  return DEFAULT_MAX_ATTEMPTS;
}

function parseBackoffMs(raw: Record<string, string>): number {
  const value = Number(raw.backoffMs);
  if (Number.isInteger(value) && value >= 0) {
    return value;
  }
  return DEFAULT_BACKOFF_MS;
}

function parseJitter(raw: Record<string, string>): boolean {
  if (raw.jitter === "true") return true;
  if (raw.jitter === "false") return false;
  return true;
}

function parseMode(raw: Record<string, string>): "exponential" | "linear" {
  return VALID_MODES[raw.mode] ?? "exponential";
}

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  return {
    maxAttempts: parseMaxAttempts(raw),
    backoffMs: parseBackoffMs(raw),
    jitter: parseJitter(raw),
    mode: parseMode(raw),
  };
}

