export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const COST_TABLE: Record<ShipmentOrder["zone"], [number, number, number, number]> = {
  domestic:    [4, 7, 12, 20],
  regional:    [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function lookupBaseCost(zone: ShipmentOrder["zone"], weightKg: number): number {
  if (weightKg <= 1) return COST_TABLE[zone][0];
  if (weightKg <= 5) return COST_TABLE[zone][1];
  if (weightKg <= 20) return COST_TABLE[zone][2];
  return COST_TABLE[zone][3];
}

export function shippingCost(order: ShipmentOrder): number {
  let base = lookupBaseCost(order.zone, order.weightKg);

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const WEIGHT_TIERS = [1, 5, 20, Infinity] as const;

const BASE_COSTS: Record<ShipmentOrder["zone"], number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

export function shippingCost(order: ShipmentOrder): number {
  const costs = BASE_COSTS[order.zone];

  const weightTier = WEIGHT_TIERS.findIndex(
    (limit) => order.weightKg <= limit
  );

  let base = costs[weightTier];

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const PRICE_TIERS: number[][] = [
  [4, 7, 12, 20],
  [9, 15, 25, 40],
  [18, 30, 55],
];

const ZONE_INDEX: Record<string, number> = {
  domestic: 0,
  regional: 1,
  international: 2,
};

const WEIGHT_THRESHOLDS: number[][] = [
  [1, 5, 20, Infinity],
  [1, 5, 20, Infinity],
  [1, 5],
];

function getBasePrice(zoneIndex: number, weightKg: number): number {
  const thresholds = WEIGHT_THRESHOLDS[zoneIndex];
  const prices = PRICE_TIERS[zoneIndex];

  for (let i = 0; i < thresholds.length; i++) {
    if (weightKg <= thresholds[i]) {
      return prices[i];
    }
  }
  return prices[prices.length - 1];
}

export function shippingCost(order: ShipmentOrder): number {
  const base = getBasePrice(ZONE_INDEX[order.zone], order.weightKg);

  let cost = order.priority ? base * 2 : base;

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const BASE_RATES: Record<ShipmentOrder["zone"], [number, number, number, number]> = {
  domestic:   [4, 7, 12, 20],
  regional:   [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

const WEIGHT_TIERS = [1, 5, 20];

function getBaseRate(zone: ShipmentOrder["zone"], weightKg: number): number {
  const rates = BASE_RATES[zone];
  let tierIndex = 0;
  for (let i = 0; i < WEIGHT_TIERS.length; i++) {
    if (weightKg <= WEIGHT_TIERS[i]) {
      tierIndex = i;
      break;
    } else {
      tierIndex = i + 1;
    }
  }
  return rates[tierIndex];
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = getBaseRate(order.zone, order.weightKg);

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const WEIGHT_TIERS = [
  { max: 1 },
  { max: 5 },
  { max: 20 },
];

const BASE_COSTS: Record<string, number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function getTierIndex(weightKg: number): number {
  for (let i = 0; i < WEIGHT_TIERS.length; i++) {
    if (weightKg <= WEIGHT_TIERS[i].max) return i;
  }
  return WEIGHT_TIERS.length;
}

export function shippingCost(order: ShipmentOrder): number {
  let base = BASE_COSTS[order.zone][getTierIndex(order.weightKg)];

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

type WeightTier = "light" | "medium" | "heavy" | "overweight";

const BASE_COSTS: Record<ShipmentOrder["zone"], Record<WeightTier, number>> = {
  domestic: {
    light: 4,
    medium: 7,
    heavy: 12,
    overweight: 20,
  },
  regional: {
    light: 9,
    medium: 15,
    heavy: 25,
    overweight: 40,
  },
  international: {
    light: 18,
    medium: 30,
    heavy: 55,
    overweight: 55,
  },
};

function getWeightTier(weightKg: number): WeightTier {
  if (weightKg <= 1) return "light";
  if (weightKg <= 5) return "medium";
  if (weightKg <= 20) return "heavy";
  return "overweight";
}

export function shippingCost(order: ShipmentOrder): number {
  const tier = getWeightTier(order.weightKg);
  let cost = BASE_COSTS[order.zone][tier];

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const ZONE_WEIGHT_LIMITS = [1, 5, 20] as const;

const BASE_COSTS: Record<string, number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55],
};

function getBaseCost(zone: string, weightKg: number): number {
  const costs = BASE_COSTS[zone];
  let bracket = costs.length - 1;
  for (let i = 0; i < ZONE_WEIGHT_LIMITS.length; i++) {
    if (weightKg <= ZONE_WEIGHT_LIMITS[i]) {
      bracket = i;
      break;
    }
  }
  return costs[bracket];
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = getBaseCost(order.zone, order.weightKg);

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

export function shippingCost(order: ShipmentOrder): number {
  const BASE_COSTS: Record<string, number[]> = {
    domestic: [4, 7, 12, 20],
    regional: [9, 15, 25, 40],
    international: [18, 30, 55],
  };

  const weightTiers = [1, 5, 20];
  let tier = 0;
  for (const limit of weightTiers) {
    if (order.weightKg > limit) {
      tier++;
    } else {
      break;
    }
  }

  let base = BASE_COSTS[order.zone][Math.min(tier, BASE_COSTS[order.zone].length - 1)];

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

files.process_batch.ts:
export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"] as const);

const SEVERITY_RANK: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  const labels: string[] = [];
  const alerts: string[] = [];
  const worstRef = { current: "standby" };

  for (const entry of entries) {
    const outcome = parseReading(entry, parsed.length);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    const { millivolts, label } = processSingleReading(outcome, alerts, worstRef);
    parsed.push({ channel: outcome.channel, millivolts, at: outcome.at });
    labels.push(label);
  }

  const channels = buildChannelSummaries(parsed, labels);
  const report = `readings=${parsed.length};channels=${Object.keys(channels).length};alerts=${alerts.length};worst=${worstRef.current}`;
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const count = batch.readings.length;
  if (count === 0) {
    return "empty batch";
  }
  if (count > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return `reading ${index}: malformed`;
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return `reading ${index}: bad channel`;
  }
  if (!VALID_UNITS.has(record.unit as string)) {
    return `reading ${index}: bad unit`;
  }
  if (!Number.isInteger(record.value)) {
    return `reading ${index}: bad value`;
  }
  if (!isNonNegativeInt(record.at)) {
    return `reading ${index}: bad timestamp`;
  }
  return { channel: record.channel, unit: record.unit as string, value: record.value as number, at: record.at as number };
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {
  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

function severityRank(label: string): number {
  return SEVERITY_RANK[label] ?? 0;
}

function buildChannelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const label = labels[index];
    const existing = channels[reading.channel];
    if (existing === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: label };
      continue;
    }
    existing.count += 1;
    if (reading.millivolts < existing.min) {
      existing.min = reading.millivolts;
    }
    if (reading.millivolts > existing.max) {
      existing.max = reading.millivolts;
    }
    if (SEVERITY_RANK[label] > SEVERITY_RANK[existing.worst]) {
      existing.worst = label;
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, worst: string): string {
  return `readings=${readingCount};channels=${channelCount};alerts=${alertCount};worst=${worst}`;
}

function processSingleReading(
  reading: Reading,
  alerts: string[],
  worstRef: { current: string },
): { millivolts: number; label: string } {
  const millivolts = normalizeValue(reading.unit, reading.value);
  const label = classifySignal(millivolts);

  if (millivolts >= 900) {
    alerts.push(`${reading.channel}:critical`);
  } else if (millivolts < 0) {
    alerts.push(`${reading.channel}:negative`);
  } else if (millivolts >= 600 && millivolts < 900) {
    alerts.push(`${reading.channel}:loaded`);
  }

  if (SEVERITY_RANK[label] > SEVERITY_RANK[worstRef.current]) {
    worstRef.current = label;
  }

  return { millivolts, label };
}

export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"]);

interface BatchInput {
  readings: unknown[];
}

export function processBatch(raw: unknown): BatchResult {
  const error = validateBatch(raw);
  if (error !== null) {
    return { ok: false, error };
  }
  const batch = raw as BatchInput;
  const parsed: ParsedReading[] = [];
  for (let i = 0; i < batch.readings.length; i++) {
    const result = parseReading(batch.readings[i], i);
    if (typeof result === "string") {
      return { ok: false, error: result };
    }
    parsed.push({
      channel: result.channel,
      millivolts: normalizeValue(result.unit, result.value),
      at: result.at,
    });
  }

  const labels = parsed.map((r) => classifySignal(r.millivolts));
  const alerts = collectAlerts(parsed);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (raw === null || typeof raw !== "object") {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const readings = batch.readings as unknown[];
  if (readings.length === 0) {
    return "empty batch";
  }
  if (readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  const check = validateEntry(entry, index);
  if (check !== null) {
    return check;
  }
  const r = entry as Record<string, unknown>;

  const channelErr = validateChannel(r, index);
  if (channelErr !== null) return channelErr;
  const unitErr = validateUnit(r, index);
  if (unitErr !== null) return unitErr;
  const valueErr = validateValue(r, index);
  if (valueErr !== null) return valueErr;
  const atErr = validateTimestamp(r, index);
  if (atErr !== null) return atErr;

  return { channel: r.channel, unit: r.unit, value: r.value, at: r.at };
}

function validateEntry(entry: unknown, index: number): string | null {
  if (entry === null || typeof entry !== "object") {
    return `reading ${index}: malformed`;
  }
  return null;
}

function validateChannel(r: Record<string, unknown>, index: number): string | null {
  if (typeof r.channel !== "string" || r.channel.length === 0) {
    return `reading ${index}: bad channel`;
  }
  return null;
}

function validateUnit(r: Record<string, unknown>, index: number): string | null {
  if (typeof r.unit !== "string" || !VALID_UNITS.has(r.unit)) {
    return `reading ${index}: bad unit`;
  }
  return null;
}

function validateValue(r: Record<string, unknown>, index: number): string | null {
  if (typeof r.value !== "number" || !Number.isInteger(r.value)) {
    return `reading ${index}: bad value`;
  }
  return null;
}

function validateTimestamp(r: Record<string, unknown>, index: number): string | null {
  if (typeof r.at !== "number" || !isNonNegativeInt(r.at)) {
    return `reading ${index}: bad timestamp`;
  }
  return null;
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {
  if (millivolts < 0) {
    return "negative";
  }
  if (millivolts < 50) {
    return "standby";
  }
  if (millivolts < 200) {
    return "idle";
  }
  if (millivolts < 600) {
    return "active";
  }
  if (millivolts < 900) {
    return "loaded";
  }
  return "critical";
}

function severityRank(label: string): number {
  if (label === "negative") {
    return 5;
  }
  if (label === "critical") {
    return 4;
  }
  if (label === "loaded") {
    return 3;
  }
  if (label === "active") {
    return 2;
  }
  if (label === "idle") {
    return 1;
  }
  return 0;
}

function collectAlerts(parsed: ParsedReading[]): string[] {
  const alerts: string[] = [];
  for (const reading of parsed) {
    if (reading.millivolts >= 900) {
      alerts.push(`${reading.channel}:critical`);
    } else if (reading.millivolts < 0) {
      alerts.push(`${reading.channel}:negative`);
    } else if (reading.millivolts >= 600) {
      alerts.push(`${reading.channel}:loaded`);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let i = 0; i < parsed.length; i++) {
    const reading = parsed[i];
    const label = labels[i];
    const summary = channels[reading.channel];
    if (summary === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: label };
      continue;
    }
    summary.count++;
    if (reading.millivolts < summary.min) {
      summary.min = reading.millivolts;
    }
    if (reading.millivolts > summary.max) {
      summary.max = reading.millivolts;
    }
    if (severityRank(label) > severityRank(summary.worst)) {
      summary.worst = label;
    }
  }
