}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const length = batch.readings.length;
  if (length === 0) {
    return "empty batch";
  }
  if (length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  if (!UNITS.has(record.unit as string)) {
    return "reading " + index + ": bad unit";
  }
  if (!Number.isInteger(record.value)) {
    return "reading " + index + ": bad value";
  }
  if (!isNonNegativeInt(record.at)) {
    return "reading " + index + ": bad timestamp";
  }
  return { channel: record.channel, unit: record.unit as string, value: record.value as number, at: record.at as number };
}

function isNonNegativeInt(value: unknown): boolean {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {
  if (millivolts < 0) return "negative";
  if (millivolts < 50) return "standby";
  if (millivolts < 200) return "idle";
  if (millivolts < 600) return "active";
  if (millivolts < 900) return "loaded";
  return "critical";
}

const SEVERITY_RANK: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

function severityRank(label: string): number {
  return SEVERITY_RANK[label] ?? -1;
}

function collectAlerts(parsed: ParsedReading[]): string[] {
  const alerts: string[] = [];
  for (const reading of parsed) {
    const label = classifySignal(reading.millivolts);
    if (label === "critical" || label === "negative" || label === "loaded") {
      alerts.push(reading.channel + ":" + label);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const channel = channels[reading.channel];
    if (channel === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: labels[index] };
      continue;
    }
    channel.count++;
    if (reading.millivolts < channel.min) channel.min = reading.millivolts;
    if (reading.millivolts > channel.max) channel.max = reading.millivolts;
    if (severityRank(labels[index]) > severityRank(channel.worst)) {
      channel.worst = labels[index];
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }
  }
  return `readings=${readingCount};channels=${channelCount};alerts=${alertCount};worst=${worst}`;
}

export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

type ParseResult =
  | { ok: true; reading: Reading }
  | { ok: false; error: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function makeError(index: number, field: string): string {
  return "reading " + index + ": bad " + field;
}

function validateChannel(record: Record<string, unknown>, index: number): string | null {
  const channel = record.channel;
  if (typeof channel !== "string" || channel.length === 0) {
    return makeError(index, "channel");
  }
  return null;
}

function validateUnit(record: Record<string, unknown>, index: number): string | null {
  const unit = record.unit;
  if (typeof unit !== "string" || !VALID_UNITS.has(unit)) {
    return makeError(index, "unit");
  }
  return null;
}

function validateValue(record: Record<string, unknown>, index: number): string | null {
  const value = record.value;
  if (!Number.isInteger(value)) {
    return makeError(index, "value");
  }
  return null;
}

function validateTimestamp(record: Record<string, unknown>, index: number): string | null {
  const at = record.at;
  if (!isNonNegativeInt(at)) {
    return makeError(index, "timestamp");
  }
  return null;
}

function parseReading(entry: unknown, index: number): ParseResult {
  if (!isRecord(entry)) {
    return { ok: false, error: "reading " + index + ": malformed" };
  }

  const err = validateChannel(entry, index);
  if (err !== null) return { ok: false, error: err };

  const unitErr = validateUnit(entry, index);
  if (unitErr !== null) return { ok: false, error: unitErr };

  const valueErr = validateValue(entry, index);
  if (valueErr !== null) return { ok: false, error: valueErr };

  const timestampErr = validateTimestamp(entry, index);
  if (timestampErr !== null) return { ok: false, error: timestampErr };

  return {
    ok: true,
    reading: {
      channel: entry.channel as string,
      unit: entry.unit as string,
      value: entry.value as number,
      at: entry.at as number,
    },
  };
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const VALID_UNITS = new Set(["uV", "mV", "V"]);

const SEVERITY_RANK: Record<string, number> = {
  negative: 5,
  critical: 4,
  loaded: 3,
  active: 2,
  idle: 1,
  standby: 0,
};

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (!outcome.ok) {
      return { ok: false, error: outcome.error };
    }
    const r = outcome.reading;
    parsed.push({ channel: r.channel, millivolts: normalizeValue(r.unit, r.value), at: r.at });
  }
  const labels = parsed.map((reading) => classifySignal(reading.millivolts));
  const alerts = collectAlerts(parsed);
  const channels = channelSummaries(parsed, labels);
  const report = buildReport(parsed.length, Object.keys(channels).length, alerts.length, labels);
  return { ok: true, readings: parsed.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  const length = batch.readings.length;
  if (length === 0) {
    return "empty batch";
  }
  if (length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V":
      return value * 1000;
    case "uV":
      return Math.trunc(value / 1000);
    default:
      return value;
  }
}

export function classifySignal(millivolts: number): string {
  if (millivolts < 0) {
    return "negative";
  }
  if (millivolts < 50) {
    return "standby";
  }
  if (millivolts < 200) {
    return "idle";
  }
  if (millivolts < 600) {
    return "active";
  }
  if (millivolts < 900) {
    return "loaded";
  }
  return "critical";
}

function severityRank(label: string): number {
  return SEVERITY_RANK[label] ?? 0;
}

function collectAlerts(parsed: ParsedReading[]): string[] {
  const alerts: string[] = [];
  for (const reading of parsed) {
    const label = classifySignal(reading.millivolts);
    if (label === "critical" || label === "negative" || label === "loaded") {
      alerts.push(reading.channel + ":" + label);
    }
  }
  return alerts;
}

function channelSummaries(parsed: ParsedReading[], labels: string[]): Record<string, ChannelSummary> {
  const channels: Record<string, ChannelSummary> = {};
  for (let index = 0; index < parsed.length; index++) {
    const reading = parsed[index];
    const existing = channels[reading.channel];
    if (existing === undefined) {
      channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: labels[index] };
      continue;
    }
    existing.count++;
    if (reading.millivolts < existing.min) {
      existing.min = reading.millivolts;
    }
    if (reading.millivolts > existing.max) {
      existing.max = reading.millivolts;
    }
    if (severityRank(labels[index]) > severityRank(existing.worst)) {
      existing.worst = labels[index];
    }
  }
  return channels;
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, labels: string[]): string {
  let worst = "standby";
  for (const label of labels) {
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }
  }
  return "readings=" + readingCount + ";channels=" + channelCount + ";alerts=" + alertCount + ";worst=" + worst;
}
